-- M-BUDDY v2 — thay thế TOÀN BỘ nội dung nghiệp vụ (sản phẩm/chặng/level/
-- câu hỏi) bằng bộ mới theo v2_docs/ (Kich_ban_training.md,
-- Persona_5_nhan_vat.md, MSB_Product_Knowledge_Base.md, Rule_chung.md).
-- Sinh TỰ ĐỘNG bằng app/scripts/generateContentReseedSql.mts từ
-- app/data/products.ts, personas.ts, levels.ts, quizBank.json — KHÔNG tự sửa tay.
--
-- Chạy SAU 0005_seed_content.sql, TOÀN BỘ file này 1 lần trong Supabase
-- Dashboard > SQL Editor > New query. An toàn để chạy lại (upsert theo id).
--
-- KHÔNG động tới level_progress/roleplay_history — 2 bảng đó lưu level_id
-- dạng text rời, không có FK tới bảng levels, nên tiến độ/lịch sử cũ của
-- người dùng thật (nếu có) vẫn giữ nguyên, chỉ đơn giản không còn khớp với
-- level nào trong bộ mới nếu id đó đã bị xoá.

-- ============================================================
-- 0. Thêm cột mới cho nội dung v2 (idempotent)
-- ============================================================

alter table public.products add column if not exists knowledge_base text;

alter table public.personas
  add column if not exists self_address text,
  add column if not exists seller_address text,
  add column if not exists speaking_style text,
  add column if not exists patience_note text,
  add column if not exists closing_signal text,
  add column if not exists financial_data text,
  add column if not exists hidden_data text,
  add column if not exists contrast_example text;

alter table public.levels add column if not exists training_script text;

-- ============================================================
-- 1. Xoá id cũ không còn tồn tại trong bộ mới
-- ============================================================

-- Level cũ dạng "x.5"/"4.4"/"4.5" (chặng nào cũng có đúng 5 level) — bộ mới
-- không còn cố định 5 level/chặng (chặng 4 chỉ còn 3). Xoá trước products để
-- tránh phụ thuộc thứ tự (dù đã có on delete cascade từ products).
delete from public.levels where id in ('1.1', '1.2', '1.3', '1.4', '1.5', '2.1', '2.2', '2.3', '2.4', '2.5', '3.1', '3.2', '3.3', '3.4', '3.5', '4.1', '4.2', '4.3', '4.4', '4.5', '5.1', '5.2', '5.3', '5.4', '5.5') and id not in ('1.1', '1.2', '1.3', '1.4', '2.1', '2.2', '2.3', '2.4', '3.1', '3.2', '3.3', '3.4', '4.1', '4.2', '4.3', '5.1', '5.2', '5.3', '5.4');

-- Sản phẩm cũ (5 sản phẩm mẫu chung, không còn dùng) — cascade xoá luôn mọi
-- level còn sót tham chiếu tới chúng.
delete from public.products where id in ('tiet-kiem-online', 'the-tin-dung', 'vay-tieu-dung', 'bao-hiem-lien-ket', 'combo') and id not in ('tiet-kiem-ong-vang', 'tiet-kiem-mang-non', 'tien-gui-ky-han-truc-tuyen', 'm-flexcare', 'huong-dan-mbank', 'visa-online', 'tai-khoan-luong-mpro', 'vay-mua-nha', 'tai-khoan-so-dep', 'vay-bo-sung-von', 'the-mastercard-hybrid', 'thau-chi-tieu-dung', 'bao-hiem-chung-cu-4-0', 'pru-bao-ve-toi-da', 'bao-hiem-benh-hiem-ngheo', 'combo-ca-nhan-hoa', 'chuyen-tien-quoc-te', 'vay-mua-oto-bds-ca-nhan');

-- ============================================================
-- 2. Upsert products — ghi đè theo id nếu đã tồn tại
-- ============================================================

insert into public.products
  (id, order_num, name, short_name, short_description, target_audience, benefits, basic_conditions, key_selling_points, objection_bank, compliance_note, knowledge_base)
values
('tiet-kiem-ong-vang', 1, 'Tiết kiệm Ong Vàng', null, 'Tiết kiệm gửi góp linh hoạt, giao dịch tại quầy hoặc online, kỳ hạn 3–36 tháng.', 'Khách hàng từ 18 tuổi có khoản tiền nhàn rỗi muốn gửi tiết kiệm an toàn, linh hoạt.', '["Kỳ hạn đa dạng: 3–13, 15, 18, 24, 36 tháng","Gửi lần đầu tối thiểu 1 triệu VND (hoặc 100 USD), gửi thêm tối thiểu 50.000 VND (hoặc 2 USD)","Trả lãi cuối kỳ; rút trước hạn vẫn hưởng lãi không kỳ hạn thay vì mất trắng","Rút gốc từng phần: tại quầy tối đa 5 lần, online không giới hạn"]'::jsonb, 'Khách hàng cá nhân từ 18 tuổi, tiền gửi ban đầu tối thiểu 1 triệu VND/100 USD.', '["Kỳ hạn linh hoạt 3–36 tháng, VND hoặc USD","Rút trước hạn không mất hết lãi (hưởng lãi không kỳ hạn)","Có thể mở/quản lý ngay trên MSB Digital Bank","Đáo hạn tự động chuyển sang sản phẩm lãi suất cao nhất tương ứng nếu không tất toán"]'::jsonb, '[{"question":"Gửi online có an toàn không?","sampleAnswer":"An toàn tương đương tại quầy, sổ tiết kiệm điện tử có giá trị pháp lý như sổ giấy, tiền gửi được bảo hiểm theo quy định."},{"question":"Rút trước hạn có mất hết lãi không?","sampleAnswer":"Không mất hết — phần đã gửi vẫn được hưởng lãi không kỳ hạn, chỉ thấp hơn lãi kỳ hạn ban đầu, gốc giữ nguyên."},{"question":"Không tất toán khi đáo hạn thì sao?","sampleAnswer":"Hệ thống tự động chuyển cả gốc và lãi sang sản phẩm \"Tiết kiệm lãi suất cao nhất\" cho kỳ hạn tương ứng nếu không có thoả thuận khác."}]'::jsonb, null, 'Tiết kiệm Ong Vàng — giải pháp tiết kiệm gửi góp linh hoạt cho khách hàng từ 18 tuổi, giao dịch tại quầy hoặc trực tuyến.
Đặc điểm: kỳ hạn 3–13/15/18/24/36 tháng; tiền tệ VND hoặc USD; tiền gửi ban đầu tối thiểu 1 triệu VND hoặc 100 USD; gửi thêm định kỳ tối thiểu 50.000 VND hoặc 2 USD; trả lãi cuối kỳ; rút trước hạn hưởng lãi không kỳ hạn theo chính sách.
Đáo hạn: nếu không tất toán và không có thoả thuận khác, MSB tự động chuyển cả gốc + lãi sang sản phẩm "Tiết kiệm lãi suất cao nhất" cho kỳ hạn tương ứng theo mức lãi suất áp dụng tại thời điểm đó.
Mở online: đăng nhập MSB Digital Bank → Tiền gửi và đầu tư → Mở mới tiền gửi → chọn sản phẩm → nhập tài khoản nguồn/số tiền/kỳ hạn/lãi suất/phương thức đáo hạn → đồng ý điều khoản → xác thực → hoàn tất.
FAQ: rút gốc từng phần tại quầy tối đa 5 lần, online không giới hạn; có thể ủy quyền người khác tất toán tại quầy theo quy định; có thể mở tối đa 10 sổ/lần cho mục đích bảo mật.'),
('tiet-kiem-mang-non', 2, 'Tiết kiệm Măng Non', null, 'Tiết kiệm gửi góp dành cho mục tiêu tích lũy cho con, kỳ hạn tới 15 năm.', 'Cha mẹ muốn tích lũy học phí hoặc tạo quỹ dài hạn cho con.', '["Kỳ hạn linh hoạt: 3–13, 15, 18, 24, 36 tháng, hoặc dài hạn 4–15 năm","Gửi lần đầu ≥1 triệu VND/100 USD, gửi thêm ≥50.000 VND/2 USD","Trả lãi cuối kỳ, có thể rút trước hạn với lãi không kỳ hạn","Người lớn đứng tên gửi/đại diện theo quy định"]'::jsonb, 'Người đại diện hợp pháp đứng tên gửi cho trẻ, gửi lần đầu tối thiểu 1 triệu VND/100 USD.', '["Kỳ hạn dài tới 15 năm, phù hợp mục tiêu học phí/quỹ tương lai cho con","Gửi góp định kỳ, không cần 1 khoản lớn ngay từ đầu","Vẫn rút trước hạn được nếu cần gấp"]'::jsonb, '[{"question":"Khác gì tiết kiệm thường?","sampleAnswer":"Cùng cơ chế tiết kiệm gửi góp nhưng có thêm kỳ hạn dài 4–15 năm, phù hợp mục tiêu tích lũy dài hạn cho con thay vì chỉ gửi ngắn hạn."},{"question":"Rút trước hạn thì sao?","sampleAnswer":"Vẫn rút được, phần đã gửi hưởng lãi không kỳ hạn, không mất gốc."}]'::jsonb, null, 'Tiết kiệm Măng Non — sản phẩm gửi góp dành cho mục tiêu tích lũy cho trẻ, người lớn là người đứng tên gửi/đại diện theo quy định.
Đặc điểm: kỳ hạn 3–13/15/18/24/36 tháng hoặc 4–15 năm; tiền tệ VND/USD; gửi lần đầu ≥1 triệu VND hoặc ≥100 USD; gửi thêm ≥50.000 VND hoặc ≥2 USD; trả lãi cuối kỳ; có thể rút trước hạn với lãi không kỳ hạn.
Sales Trigger: cha mẹ muốn tích lũy học phí; muốn tạo quỹ dài hạn cho con; muốn gửi đều đặn thay vì bỏ một khoản tiền lớn ngay từ đầu.'),
('tien-gui-ky-han-truc-tuyen', 3, 'Tiền gửi có kỳ hạn trực tuyến', null, 'Kênh gửi tiết kiệm có kỳ hạn qua MSB Digital Bank/mBank, lãi suất online có thể cao hơn tại quầy.', 'Khách hàng cá nhân cư trú tại Việt Nam, từ 18 tuổi, đã có tài khoản thanh toán MSB.', '["Giao dịch mọi lúc mọi nơi, không cần ra quầy","Lãi suất online có thể cao hơn tại quầy tới 0,5% tuỳ kỳ hạn/thời điểm","Số tiền gửi tối thiểu chỉ 1 triệu VND","Không mất gốc khi rút trước hạn — chỉ tính lại lãi theo mức không kỳ hạn"]'::jsonb, 'Từ 18 tuổi, đã có tài khoản thanh toán MSB, số tiền tối thiểu 1 triệu VND.', '["Không mất gốc khi rút trước hạn, không có phí ẩn dạng \"phí phá hợp đồng\"","Được bảo vệ bởi bảo hiểm tiền gửi tối đa 350 triệu đồng/người (gồm gốc và lãi)","Lãi tiền gửi được miễn thuế thu nhập cá nhân theo quy định hiện hành","Tự động quay vòng kỳ hạn mới theo lãi suất công bố nếu không tất toán khi đáo hạn"]'::jsonb, '[{"question":"Có mất gốc khi rút trước hạn không?","sampleAnswer":"Không. Chỉ có phần lãi bị tính lại thấp hơn theo lãi suất không kỳ hạn tại thời điểm rút, gốc giữ nguyên."},{"question":"Có phí ẩn không?","sampleAnswer":"Không có phí ẩn dạng phí phá hợp đồng như bảo hiểm liên kết đầu tư — chỉ là cơ chế tính lại lãi khi rút sớm, đã công khai theo điều kiện sản phẩm."},{"question":"Ngân hàng có vấn đề thì tiền của tôi sao?","sampleAnswer":"Tiền gửi được bảo hiểm tiền gửi bảo vệ tối đa 350 triệu đồng/người (gồm cả gốc và lãi) theo quy định hiện hành."},{"question":"Có phải đóng thuế lãi tiền gửi không?","sampleAnswer":"Không — lãi tiền gửi tại tổ chức tín dụng thuộc diện miễn thuế thu nhập cá nhân theo quy định hiện hành."}]'::jsonb, null, 'Tiền gửi có kỳ hạn trực tuyến — gửi online qua MSB Digital Bank/MSB mBank.
Điểm nổi bật: giao dịch mọi lúc mọi nơi; lãi suất online có thể cao hơn quầy theo từng sản phẩm/chính sách (tới 0,5% theo công bố MSB); quản lý tiền gửi online; có các phương án trả lãi tuỳ sản phẩm.
Điều kiện: khách hàng cá nhân Việt Nam cư trú, từ 18 tuổi, có tài khoản thanh toán MSB, số tiền tối thiểu 1 triệu VND.
Đáo hạn: nếu bật tự động quay vòng và không tất toán khi đáo hạn, hệ thống tự động chuyển sang kỳ hạn mới theo lãi suất công bố tại thời điểm quay vòng.
Bảng câu trả lời chuẩn (đối chiếu KB, để AI không bịa số liệu ngoài phạm vi):
- Mất gốc khi rút trước hạn? Không, chỉ phần lãi bị tính lại thấp hơn (theo lãi suất tiền gửi không kỳ hạn thấp nhất tại thời điểm rút), gốc giữ nguyên.
- Rút trước hạn thì sao? Được rút, nhưng không còn hưởng lãi suất kỳ hạn ban đầu cho phần rút trước hạn — áp mức lãi không kỳ hạn (thấp hơn nhiều).
- Có phí ẩn không? Không có phí ẩn dạng "phí phá hợp đồng" như bảo hiểm liên kết đầu tư — chỉ là cơ chế tính lại lãi suất khi rút sớm, đã nêu công khai theo điều kiện sản phẩm.
- Lãi suất online so với tại quầy? Có thể cao hơn tới 0,5% so với tại quầy theo công bố của MSB — mức cụ thể tuỳ kỳ hạn/thời điểm, không phải một con số cố định.
- Nếu ngân hàng có vấn đề thì sao? Tiền gửi được bảo hiểm tiền gửi bảo vệ tối đa 350 triệu đồng/người/tổ chức (gồm cả gốc và lãi) theo quy định hiện hành.
- Có phải đóng thuế lãi tiền gửi không? Không — thu nhập từ lãi tiền gửi tại tổ chức tín dụng thuộc diện miễn thuế thu nhập cá nhân theo quy định hiện hành.
Lưu ý cho AI đóng vai: không tự ý đưa ra một con số lãi suất % cụ thể cố định nếu KB không có — nếu Sale chốt cứng "chắc chắn không đổi", khách được phép tỏ ra nghi ngờ nhẹ vì bản chất lãi suất tiền gửi thay đổi theo thời điểm/kỳ hạn/kênh.'),
('m-flexcare', 4, 'M-FlexCare', 'M-Flexcare', 'Bảo hiểm sức khỏe toàn cầu cho cá nhân/gia đình, hỗ trợ nội trú, ngoại trú, tai nạn, thai sản.', 'Cá nhân/gia đình từ 60 ngày tuổi đến 65 tuổi muốn bảo vệ sức khỏe toàn diện.', '["4 chương trình: Đồng, Vàng, Bạch Kim, Kim Cương — quyền lợi tăng dần","Chi trả nội trú, ngoại trú, nha khoa, thai sản, phẫu thuật, xe cấp cứu, điều dưỡng tại nhà...","Trẻ dưới 6 tuổi tham gia cùng cha/mẹ trong cùng hợp đồng","Đóng phí hàng năm, thời hạn 1 năm"]'::jsonb, 'Tham gia từ 60 ngày tuổi, kết thúc tối đa 65 tuổi theo điều kiện; đóng phí hàng năm.', '["Quyền lợi rộng: tai nạn, bệnh tật, thai sản, nha khoa, phục hồi chức năng","4 mức chương trình phù hợp nhiều ngân sách khác nhau","Thời gian chờ rõ ràng theo từng loại quyền lợi (tai nạn hiệu lực ngay, thai sản 60 ngày...)"]'::jsonb, '[{"question":"Tôi đã có bảo hiểm sức khỏe/BHYT rồi.","sampleAnswer":"Có thể có nhiều hợp đồng bảo hiểm sức khỏe cùng lúc, nhưng tổng chi trả bị giới hạn theo hóa đơn/quyền lợi hợp đồng — nên vẫn có thể bổ sung để tăng mức bảo vệ."}]'::jsonb, null, 'M-FlexCare — bảo hiểm sức khỏe toàn cầu cho cá nhân/gia đình, hỗ trợ chi phí điều trị nội trú, ngoại trú, tai nạn, thai sản và các quyền lợi bổ sung tùy chương trình.
Độ tuổi: từ 60 ngày tuổi, kết thúc tối đa 65 tuổi; trẻ dưới 6 tuổi cần tham gia cùng cha/mẹ trong cùng hợp đồng.
Thời hạn: 1 năm, phí đóng hàng năm.
Thời gian chờ chính: tai nạn hiệu lực ngay sau khi đóng đủ phí; nha khoa/bệnh thông thường 30 ngày; thai sản/tình trạng liên quan 60 ngày; sinh thường/sinh mổ 270 ngày; bệnh có sẵn/đặc biệt 365 ngày trong năm đầu hoặc khi không tái tục liên tục.
Các chương trình: Đồng, Vàng, Bạch Kim, Kim Cương.
Một số quyền lợi theo chương trình (Đồng/Vàng/Bạch Kim/Kim Cương): tử vong/TTTBVV do tai nạn 200m/500m/1 tỷ/2 tỷ; chi phí y tế do tai nạn 20m/50m/100m/200m; nội trú bệnh/tật/thai sản/năm 75m/150m/300m/450m; trợ cấp ngày nằm viện 1,5m/3m/7m/12m; phẫu thuật/năm 50m/100m/200m/300m; ngoại trú+nha khoa/năm 5m/12m/20m/30m; thai sản/năm 10m/20m/40m/60m; tử vong do bệnh/TTTBVV 100m/250m/500m/1 tỷ.
Quyền lợi chi tiết khác: trước nhập viện, sau xuất viện, xe cấp cứu, điều dưỡng tại nhà, phục hồi chức năng, điều trị ung thư, trợ cấp bệnh viện công, nha khoa, thai sản.
FAQ: có thể có nhiều hợp đồng bảo hiểm sức khỏe nhưng tổng chi trả bị giới hạn theo hóa đơn/quyền lợi hợp đồng; gia hạn trong thời gian ân hạn có thể giúp duy trì tính liên tục; vật lý trị liệu có thể được chi trả nếu có chỉ định y khoa và đáp ứng điều kiện.'),
('huong-dan-mbank', 5, 'Hướng dẫn mở sổ tiết kiệm online / dùng MSB mBank', 'Hướng dẫn app mBank', 'Hướng dẫn khách thao tác mở sổ tiết kiệm/ngân hàng số ngay trên app MSB Digital Bank/mBank.', 'Khách hàng đã đồng ý dùng sản phẩm online nhưng chưa quen thao tác app.', '["Quy trình 9 bước rõ ràng, có thể làm mẫu cùng khách ngay tại quầy/qua điện thoại","Không mất phí thao tác","Có hỗ trợ hotline nếu khách cần trợ giúp thêm"]'::jsonb, 'Khách đã có tài khoản MSB Digital Bank hoặc sẵn sàng đăng ký mới.', '["Thao tác đơn giản, có hướng dẫn từng bước","Nhân viên có thể ngồi cạnh hướng dẫn trực tiếp lần đầu"]'::jsonb, '[{"question":"Tôi không rành công nghệ, sợ bấm nhầm mất tiền.","sampleAnswer":"Có bước xác nhận lại trước khi hoàn tất mọi giao dịch, không mất tiền do bấm nhầm; nhân viên có thể hướng dẫn từng bước tới khi khách tự tin thao tác."}]'::jsonb, null, 'Hướng dẫn mở sổ tiết kiệm online — quy trình chuẩn: Đăng nhập MSB Digital Bank → Tiền gửi và đầu tư → Mở mới tiền gửi → Chọn sản phẩm → Nhập tài khoản nguồn + số tiền + kỳ hạn/lãi suất → Chọn phương thức đáo hạn → Đồng ý điều khoản → Xác thực → Mở thành công → Theo dõi khoản tiền gửi trên app.
Sales Trigger — nếu khách hàng nói: "Tôi không muốn ra ngân hàng", "Tôi muốn gửi tiền lúc tối", "Có thể mở trên app không?", "Tôi muốn chia tiền thành nhiều sổ" → Sales nên dẫn sang tiền gửi online và hướng dẫn thao tác trực tiếp.'),
('visa-online', 6, 'MSB Visa Online', 'Thẻ Visa Online', 'Thẻ tín dụng hoàn 10% chi tiêu online (Shopee, Lazada, TikTok, vé xem phim...), phí thường niên 399.000đ/năm.', 'Khách hàng trẻ, mua sắm/thanh toán thương mại điện tử thường xuyên, thu nhập từ 5 triệu/tháng.', '["Hoàn 10% chi tiêu online khi đạt 3 triệu/kỳ sao kê","Phí thường niên 399.000đ/năm, được hoàn năm đầu nếu chi ≥500.000đ/30 ngày","Hoàn phí năm sau nếu chi tiêu năm trước ≥60 triệu","Hạn mức từ 100 triệu, thu nhập tham chiếu chỉ từ 5 triệu/tháng"]'::jsonb, 'Từ 18–65 tuổi (lưu ý FAQ hiện hành ghi 20 tuổi trở lên), thu nhập chuyển khoản từ 5 triệu/tháng.', '["Hoàn tiền cao (10%) đúng nhóm chi tiêu online phổ biến với người trẻ","Thu nhập yêu cầu thấp nhất trong nhóm thẻ hoàn tiền của MSB","Có thể được miễn phí thường niên nếu duy trì chi tiêu đều"]'::jsonb, '[{"question":"Phí thường niên có đắt không?","sampleAnswer":"Chỉ 399.000đ/năm, được hoàn ngay năm đầu nếu chi từ 500.000đ trong 30 ngày đầu, và hoàn tiếp các năm sau nếu chi tiêu năm trước đạt 60 triệu."},{"question":"Tôi chỉ mua hàng online thôi.","sampleAnswer":"Đúng đối tượng luôn — thẻ hoàn 10% đúng nhóm chi tiêu online như Shopee, Lazada, TikTok, vé xem phim khi đạt 3 triệu/kỳ sao kê."}]'::jsonb, null, 'MSB Visa Online. Ưu đãi: hoàn 10% chi tiêu online (Shopee, Lazada, TikTok, vé xem phim CGV/BHD/Galaxy/Lotte/Cinestar...), điều kiện tổng chi tiêu đạt 3 triệu/kỳ sao kê.
Phí và điều kiện: phí thường niên 399.000 VNĐ/năm; hoàn năm đầu nếu chi ≥500.000/30 ngày; hoàn năm sau nếu chi tiêu năm trước ≥60 triệu; hạn mức 100 triệu; thẻ phụ 3; độ tuổi 18–65 (lưu ý: FAQ hiện hành của MSB nêu điều kiện chung 20 tuổi trở lên, cần re-validate); thu nhập chuyển khoản từ 5 triệu/tháng — thấp nhất trong nhóm thẻ hoàn tiền.
Đặc điểm chung nhóm thẻ tín dụng MSB: trả góp 0% lãi suất tới 12 tháng tại Samsung, Nguyễn Kim, FPT Shop, CellphoneS; hỗ trợ Apple Pay/Samsung Pay và Contactless theo kênh. Hồ sơ cơ bản: đơn đăng ký, CCCD gắn chip hoặc giấy tờ tùy thân hợp lệ, giấy tờ chứng minh thu nhập/tài sản theo chính sách.
Trigger: khách hàng mua sắm online, đặt vé/xem phim, thanh toán thương mại điện tử.'),
('tai-khoan-luong-mpro', 7, 'Tài khoản lương + gói M-Pro', 'Tài khoản lương + M-Pro', 'Mở tài khoản nhận lương qua MSB kèm gói dịch vụ M-Pro (miễn nhiều loại phí giao dịch cơ bản).', 'Người vừa chuyển việc/công ty mới trả lương qua MSB.', '["Mở tài khoản nhanh, có thể làm online không cần ra quầy","M-Pro miễn phí phát hành thẻ, miễn phí Internet/Mobile Banking","Miễn phí duy trì gói nếu số dư bình quân ≥2 triệu"]'::jsonb, 'Có quyết định/xác nhận lương chuyển khoản qua MSB từ công ty.', '["Thao tác mở tài khoản hoàn toàn online, không mất phí thêm","Gói M-Pro đi kèm không phát sinh phí nếu duy trì số dư tối thiểu"]'::jsonb, '[{"question":"Gói M-Pro có tốn phí gì thêm không?","sampleAnswer":"Không phát sinh phí thêm nếu số dư bình quân từ 2 triệu trở lên; dưới mức đó mới áp phí duy trì gói theo biểu phí hiện hành."}]'::jsonb, null, 'M-Pro — CẢNH BÁO DỮ LIỆU: thông tin dưới đây lấy từ biểu phí PDF năm 2022, không được coi là biểu phí hiện hành nếu chưa re-validate; chỉ dùng để role-play ở mức khái quát, không chốt cứng số phí cụ thể với khách.
Theo PDF cũ: phí tài khoản năm miễn phí; không yêu cầu số dư tối thiểu; đi kèm Visa Debit Classic; phí phát hành thẻ miễn phí; phí thường niên thẻ 22.000 VNĐ/năm; Internet/Mobile Banking miễn phí; SMS biến động số dư 8.000 VNĐ/tháng/tài khoản; phí duy trì gói: số dư bình quân ≥2 triệu miễn phí, dưới 2 triệu 22.000 VNĐ/tháng; nộp tiền mặt miễn phí; rút tiền sau 2 ngày làm việc miễn phí, rút trong 2 ngày làm việc 0,05% (tối thiểu 20.000, tối đa 1 triệu).
Quy tắc AI: chỉ dùng M-Pro để role-play ở mức khái quát (có gói kèm theo tài khoản lương, không phát sinh phí nếu duy trì số dư), không nêu số phí cụ thể như một sự thật chắc chắn hiện hành.'),
('vay-mua-nha', 8, 'Vay mua nhà dự án', 'Vay mua nhà/BĐS', 'Vay mua nhà tại các dự án MSB liên kết, thời hạn tới 40 năm, có chương trình hỗ trợ lãi suất.', 'Người trẻ/gia đình đang tích lũy để mua căn hộ, cần vay bổ sung phần còn thiếu.', '["Thời hạn vay tới 40 năm, ân hạn gốc tối đa 60 tháng","Có chương trình lãi suất hỗ trợ 0% giai đoạn đầu tại một số dự án","Thu nhập tối thiểu chỉ từ 8 triệu/tháng"]'::jsonb, 'Tuổi 22–70 (cuối kỳ không quá 80), thu nhập tối thiểu 8 triệu/tháng, có tài sản đảm bảo (thường là chính căn nhà mua).', '["Ân hạn gốc dài (tới 60 tháng) giúp giảm áp lực trả nợ giai đoạn đầu","Áp dụng cho các dự án MSB liên kết/triển khai chính sách hỗ trợ lãi suất"]'::jsonb, '[{"question":"Tôi chưa đủ tiền, chỉ mới để dành được một phần.","sampleAnswer":"Có thể tính cụ thể phần còn thiếu để vay bổ sung — nếu cho biết giá trị căn hộ và số tiền đã có, có thể ước lượng ngay khoản vay cần thiết và khả năng trả góp hàng tháng."},{"question":"Lãi suất hỗ trợ 0% có thật không?","sampleAnswer":"Trong thời gian chủ đầu tư hỗ trợ lãi suất, khoản vay vẫn phát sinh lãi bình thường — phần hỗ trợ do chủ đầu tư thanh toán cho ngân hàng theo chương trình, khách vẫn phải trả nợ gốc và các khoản khác theo hợp đồng."}]'::jsonb, null, 'Vay mua nhà dự án. Điểm nổi bật: thời hạn tới 40 năm; lãi suất từ 0% trong các chương trình hỗ trợ theo dự án; ân hạn gốc tối đa 60 tháng.
Điều kiện: tuổi 22–70 (cuối kỳ không quá 80); thu nhập tối thiểu 8 triệu/tháng; tài sản đảm bảo là nhà mua hoặc tài sản khác đủ điều kiện; áp dụng cho các dự án MSB liên kết/triển khai chính sách.
Hồ sơ: CCCD, giấy tờ cư trú, giấy tờ tài sản đảm bảo, chứng minh thu nhập, hợp đồng mua bán/chuyển nhượng, thông báo tiến độ thanh toán của chủ đầu tư, chứng từ nộp tiền đặt cọc/thanh toán.
Lưu ý về lãi suất hỗ trợ: trong thời gian chủ đầu tư hỗ trợ lãi suất, khoản vay vẫn có phát sinh lãi; phần hỗ trợ được chủ đầu tư thanh toán cho ngân hàng theo chương trình. Khách hàng vẫn cần thực hiện nghĩa vụ trả nợ gốc và các khoản khác theo hợp đồng.'),
('tai-khoan-so-dep', 9, 'Tài khoản số đẹp', null, 'Tài khoản thanh toán cá nhân hóa bằng số đẹp (phong thủy, ngày sinh, tự chọn...).', 'Khách muốn số tài khoản dễ nhớ, hợp phong thủy, hoặc dùng cho thương hiệu kinh doanh.', '["Nhiều nhóm số: phong thủy/ngũ hành, con giáp, thần số học, tự chọn, theo ngày sinh","Số đẹp theo ngày sinh có thể miễn phí khi đăng ký trên MSB mBank","Vẫn là tài khoản thanh toán đầy đủ chức năng bình thường"]'::jsonb, 'Đăng ký qua MSB Digital Bank, một số số đẹp có phí sở hữu một lần.', '["Nhiều mức giá theo độ \"đẹp\" của số, có lựa chọn miễn phí (số theo ngày sinh)","Thao tác chọn số hoàn toàn online"]'::jsonb, '[{"question":"Có cái nào không đắt không?","sampleAnswer":"Có nhiều mức giá khác nhau tùy nhóm số — số theo ngày sinh có thể miễn phí, còn lại tùy độ đẹp sẽ có phí sở hữu một lần, có thể báo cụ thể theo tầm giá khách muốn."}]'::jsonb, null, 'Tài khoản số đẹp — tài khoản thanh toán được cá nhân hóa bằng số tài khoản đẹp.
Nhóm số: theo phong thủy/ngũ hành, theo con giáp, theo thần số học, tự chọn, theo ngày sinh.
Mở online: tải MSB Digital Bank → đăng ký người dùng → mở tài khoản thanh toán → chọn số đẹp.
Đặc điểm: vẫn là tài khoản thanh toán thông thường, có thể nhận/chuyển tiền, thanh toán hóa đơn và dùng các dịch vụ thanh toán; số đẹp ngày sinh có thể miễn phí khi đăng ký trên MSB mBank; một số số đẹp khác có thể có phí sở hữu một lần.
Sales Trigger: khách muốn số tài khoản dễ nhớ; khách kinh doanh muốn số đẹp cho thương hiệu/cá nhân; khách quan tâm phong thủy/tài lộc.'),
('vay-bo-sung-von', 10, 'Cho vay bổ sung vốn kinh doanh', 'Vay bổ sung vốn KD', 'Bổ sung vốn lưu động cho hộ kinh doanh/doanh nghiệp, kể cả kinh doanh online, lãi từ 0,55%/tháng.', 'Chủ hộ kinh doanh, chủ doanh nghiệp nhỏ, người kinh doanh online/social commerce.', '["Lãi suất từ 0,55%/tháng, hạn mức tới 50 tỷ đồng","Không yêu cầu đăng ký kinh doanh trong một số trường hợp chính sách cho phép","Thời hạn tối đa 36 tháng, đánh giá lại hạn mức định kỳ 12 tháng"]'::jsonb, 'Tuổi 20–70 (tất toán không quá 75), có hoạt động kinh doanh hợp pháp, kinh nghiệm ≥1 năm (≥2 năm nếu đăng ký online).', '["Hạn mức cao (tới 50 tỷ), phù hợp cả hộ kinh doanh nhỏ lẫn quy mô lớn hơn","Có thể vay từng lần, hạn mức tín dụng, hoặc vay trung/dài hạn tùy nhu cầu","Có thể tiếp nhận/thẩm định nhanh, giải ngân online hoặc tại chi nhánh"]'::jsonb, '[{"question":"Tôi không có đăng ký kinh doanh.","sampleAnswer":"Vẫn có thể xem xét trong một số trường hợp chính sách cho phép — nếu thuộc diện phải ĐKKD nhưng chưa có, có thể dùng chứng từ nộp thuế/phí, xác nhận của đơn vị quản lý chợ/TTTM/UBND, hoặc cam kết bổ sung ĐKKD trong 6 tháng."},{"question":"Lãi suất có cố định không?","sampleAnswer":"Lãi từ 0,55%/tháng theo thông tin sản phẩm hiện hành — mức cụ thể áp dụng theo hồ sơ và chính sách tại thời điểm vay, không cam kết cố định vĩnh viễn."}]'::jsonb, null, 'Cho vay bổ sung vốn kinh doanh. Nhu cầu: bổ sung vốn lưu động/phục vụ sản xuất kinh doanh, kể cả kinh doanh online, social commerce, e-commerce.
Điểm nổi bật: lãi suất từ 0,55%/tháng; hạn mức tới 50 tỷ đồng; không yêu cầu đăng ký kinh doanh trong các trường hợp chính sách cho phép.
Điều kiện: tuổi 20–70 (tất toán không quá 75); có hoạt động kinh doanh hợp pháp; kinh nghiệm kinh doanh ≥1 năm (≥2 năm nếu đăng ký online); đối tượng: chủ hộ kinh doanh, chủ doanh nghiệp, vợ/chồng chủ cơ sở, người góp vốn, một số doanh nghiệp siêu nhỏ.
Hồ sơ: CCCD, giấy tờ cư trú, chứng minh hoạt động kinh doanh, chứng minh thu nhập, phương án vay/kế hoạch kinh doanh.
Thời hạn: tối đa 36 tháng, MSB có thể đánh giá lại hạn mức định kỳ 12 tháng.
Phương thức: vay từng lần, hạn mức tín dụng, vay trung/dài hạn.
Quy trình: online có thể được tiếp nhận/thẩm định nhanh theo chính sách; giải ngân online hoặc tại chi nhánh tùy trường hợp.'),
('the-mastercard-hybrid', 11, 'MSB Mastercard Hybrid', 'Thẻ Hybrid', 'Thẻ 2-trong-1 tích hợp chức năng ghi nợ + tín dụng, có cơ chế tích điểm/hoàn tiền.', 'Khách hàng muốn 1 thẻ duy nhất dùng được cả 2 chế độ ghi nợ và tín dụng.', '["Tích hợp ghi nợ + tín dụng trong 1 thẻ","Có cơ chế tích điểm/hoàn tiền theo chính sách sản phẩm"]'::jsonb, 'Theo chính sách phát hành thẻ hiện hành của MSB (dữ liệu sơ bộ, cần re-validate trước khi tư vấn số liệu cụ thể).', '["Gọn 1 thẻ thay vì phải mang 2 thẻ riêng (ghi nợ + tín dụng)","Phù hợp khách đã quen giao dịch tại quầy/ATM, muốn nâng cấp thêm tính năng tín dụng"]'::jsonb, '[{"question":"Khác gì thẻ ATM thường?","sampleAnswer":"Thẻ Hybrid tích hợp thêm chức năng tín dụng bên cạnh ghi nợ thông thường, tức là vẫn dùng để rút tiền/thanh toán từ tài khoản như cũ nhưng có thêm hạn mức chi tiêu trước trả sau khi cần."},{"question":"Phí có phát sinh thêm không?","sampleAnswer":"Sẽ cần kiểm tra biểu phí hiện hành theo đúng chính sách tại thời điểm đăng ký để báo chính xác, tránh nói sai số liệu."}]'::jsonb, null, 'MSB Mastercard Hybrid — thẻ 2-trong-1, tích hợp chức năng ghi nợ + tín dụng, có cơ chế tích điểm/hoàn tiền theo chính sách sản phẩm.
Lưu ý dữ liệu: sản phẩm mới có thông tin sơ bộ trong danh mục KB (mức độ hoàn thiện "Sơ bộ") — chưa đủ dữ liệu chi tiết (phí/hạn mức cụ thể) để AI dùng làm tư vấn định lượng chính xác; khi role-play, tránh chốt cứng số liệu cụ thể chưa được xác nhận.'),
('thau-chi-tieu-dung', 12, 'Thấu chi tiêu dùng', null, 'Chi tiêu trước – cân đối sau, dùng được hạn mức ngay cả khi số dư tài khoản về 0, có tài sản đảm bảo.', 'Cá nhân/hộ kinh doanh cần xoay vòng tiền mặt ngắn hạn gấp.', '["Dùng ngay khi số dư tài khoản về 0, không cần chờ duyệt lại từng lần","Chỉ tính lãi trên phần thực dùng, không tính trên cả hạn mức được cấp","Thời hạn cấp tới 12 tháng","Kinh doanh online không ĐKKD vẫn có thể được tài trợ tới 1 tỷ đồng"]'::jsonb, 'Tuổi 20–70, có tài sản đảm bảo là BĐS của khách hàng hoặc bên thứ ba.', '["Cơ chế lãi minh bạch: chỉ tính trên phần thực sự dùng","Phê duyệt nhanh (~16 giờ làm việc kể từ khi đủ hồ sơ theo dữ liệu sản phẩm)","Linh hoạt cho cả trường hợp kinh doanh chưa có ĐKKD (dùng chứng từ thay thế)"]'::jsonb, '[{"question":"Có phí ẩn không?","sampleAnswer":"Cơ chế lãi công khai trong hợp đồng, chỉ tính trên phần thực dùng — không phát sinh phí ẩn ngoài những gì đã nêu rõ khi ký."},{"question":"Tôi không có đăng ký kinh doanh.","sampleAnswer":"Nếu kinh doanh online, có thể chứng minh qua đơn hàng trên sàn TMĐT và sao kê tài khoản ngân hàng, có thể được tài trợ tới 1 tỷ đồng theo chính sách hiện hành."}]'::jsonb, null, 'Thấu chi tiêu dùng — giải pháp chi tiêu trước, cân đối sau, dùng được hạn mức ngay cả khi số dư tài khoản về 0. Thời hạn cấp tới 12 tháng, yêu cầu tài sản đảm bảo là BĐS của khách hàng hoặc bên thứ ba.
Điều kiện: tuổi 20–70; có tài sản đảm bảo (BĐS thuộc sở hữu khách hàng hoặc của bên thứ ba/người bảo lãnh); linh hoạt chứng minh thu nhập theo hồ sơ.
Hồ sơ: CMND/CCCD, sổ hộ khẩu/giấy tờ cư trú, giấy chứng nhận TSBĐ, chứng minh thu nhập, hợp đồng/đơn đặt hàng liên quan nếu cần.
Phê duyệt & giải ngân: phê duyệt khoảng 16 giờ làm việc kể từ khi đủ hồ sơ; giải ngân ngay sau khi hoàn thiện đăng ký giao dịch bảo đảm.
Trường hợp kinh doanh không có ĐKKD: không yêu cầu ĐKKD trong một số trường hợp; nếu thuộc diện phải ĐKKD nhưng chưa có, dùng 1 trong: chứng từ nộp thuế/phí, xác nhận của đơn vị quản lý chợ/TTTM/UBND phường xã, hoặc cam kết bổ sung ĐKKD trong 6 tháng. Kinh doanh online: chứng minh qua đơn hàng trên sàn TMĐT + sao kê tài khoản ngân hàng, có thể được tài trợ tới 1 tỷ đồng.'),
('bao-hiem-chung-cu-4-0', 13, 'Bảo hiểm chung cư 4.0', null, 'Bảo hiểm tài sản cho căn hộ, bảo vệ rủi ro cháy/nổ và trách nhiệm với bên thứ ba, phí từ 0,055% giá trị tài sản.', 'Chủ căn hộ, đặc biệt khách vừa vay mua nhà/chung cư.', '["Phạm vi rộng: cháy, nổ, sét, bão/lũ, vỡ đường ống nước, trộm cắp, hư hỏng, chi phí thuê nhà tạm","Trách nhiệm pháp lý với căn hộ xung quanh khi xảy ra sự cố, tới 1,2 tỷ tùy cấu hình","Phí thấp: từ 0,055% giá trị tài sản (có sprinkler) hoặc 0,1% (không sprinkler)"]'::jsonb, 'Cá nhân sống tại Việt Nam, có quyền sở hữu căn hộ theo điều kiện.', '["Phí rất thấp so với giá trị tài sản được bảo vệ","Phù hợp giới thiệu ngay khi khách vừa hoàn tất vay mua nhà"]'::jsonb, '[{"question":"Không phải ưu tiên của tôi lúc này.","sampleAnswer":"Hoàn toàn hiểu, có thể để lại thông tin ngắn gọn để tham khảo sau, không cần quyết định ngay."}]'::jsonb, null, 'Bảo hiểm chung cư 4.0 — bảo hiểm tài sản dành cho căn hộ, tập trung vào rủi ro cháy/nổ và các quyền lợi mở rộng.
Điểm nổi bật: phí từ 0,055% giá trị tài sản theo gói/điều kiện; bảo vệ căn hộ + trách nhiệm với bên thứ ba; có thể phát hành hợp đồng/policy nhanh theo kênh đăng ký.
Thời hạn: 1 năm, đóng phí hàng năm.
Phạm vi: cháy, nổ, sét, bão/lũ, vỡ đường ống nước, trộm cắp, hư hỏng, chi phí thuê nhà tạm thời, trách nhiệm pháp lý đối với căn hộ xung quanh khi xảy ra sự cố.
Mức phí chuẩn: có sprinkler 0,055% x giá trị nhà; không sprinkler 0,1% x giá trị nhà.
Các gói quyền lợi (tiêu chuẩn/ưu việt/toàn mỹ): contents 400 triệu (tối đa 20 triệu/vật) / 600 triệu (tối đa 30 triệu/vật) / 800 triệu (tối đa 50 triệu/vật); trách nhiệm bên thứ ba có thể tới 1,2 tỷ theo cấu hình.
Sales Trigger: khách mua căn hộ; khách đang vay mua nhà/chung cư; khách quan tâm bảo vệ tài sản.'),
('pru-bao-ve-toi-da', 14, 'Bảo hiểm liên kết chung Pru – Bảo vệ tối đa', 'Pru-Bảo vệ tối đa', 'Bảo hiểm nhân thọ liên kết chung do Prudential phát hành qua MSB — kết hợp bảo vệ trước rủi ro và tích lũy đầu tư.', 'Khách hàng có dòng tiền ổn định, muốn vừa bảo vệ dài hạn vừa tích lũy cho gia đình.', '["Bảo vệ trước rủi ro tử vong/thương tật toàn bộ vĩnh viễn, kết hợp tích lũy qua Giá trị tài khoản","Đóng phí linh hoạt từ năm hợp đồng thứ 5","Có cơ chế thưởng tri ân/duy trì hợp đồng nếu đóng phí liên tục nhiều năm"]'::jsonb, 'Từ 30 ngày tuổi đến 70 tuổi, có tài khoản thanh toán MSB, BẮT BUỘC đóng đủ phí 4 năm đầu.', '["Kết hợp bảo vệ + tích lũy trong 1 sản phẩm, do Prudential bảo hiểm/phát hành","Có thể rút Giá trị tài khoản đóng thêm bất kỳ lúc nào","Giá trị tài khoản cơ bản được rút từ năm hợp đồng thứ 2 (phải duy trì mức tối thiểu)"]'::jsonb, '[{"question":"Tôi sợ đóng phí nhiều năm.","sampleAnswer":"Bắt buộc đóng đủ 4 năm đầu, nhưng từ năm thứ 5 có thể tăng/giảm/tạm ngưng phí theo điều kiện hợp đồng, khá linh hoạt so với hình dung ban đầu."},{"question":"Lãi suất có đảm bảo không?","sampleAnswer":"Lãi được ghi nhận theo cơ chế Quỹ Liên kết chung, do Prudential công bố theo quy định — không thấp hơn mức lãi suất đầu tư cam kết tối thiểu theo điều khoản."},{"question":"Nếu tôi cần tiền giữa chừng thì sao?","sampleAnswer":"Giá trị tài khoản đóng thêm có thể rút bất kỳ lúc nào tới 100%; Giá trị tài khoản cơ bản được rút từ năm hợp đồng thứ 2, chỉ cần duy trì mức tối thiểu theo quy định."},{"question":"Tại sao không gửi tiết kiệm cho đơn giản?","sampleAnswer":"Đây là bảo hiểm liên kết chung — khác bản chất tiết kiệm vì vừa có bảo vệ trước rủi ro tử vong/thương tật vừa tích lũy qua Giá trị tài khoản, không phải chỉ đơn thuần gửi có lãi."}]'::jsonb, 'BẮT BUỘC giải thích đúng bản chất bảo hiểm liên kết chung (không gọi đây là "gửi tiết kiệm có lãi"), nêu rõ nghĩa vụ đóng đủ phí 4 năm đầu và không cam kết lợi nhuận cố định.', 'Bảo hiểm liên kết chung Pru – Bảo vệ tối đa. Bản chất: bảo hiểm nhân thọ liên kết chung do Prudential Việt Nam cung cấp/phát hành, phân phối qua MSB — kết hợp bảo vệ trước rủi ro tử vong/Thương tật toàn bộ vĩnh viễn (TTTBVV) và tích lũy/đầu tư qua Giá trị tài khoản. Giải pháp hoạch định tài chính dài hạn, đóng phí linh hoạt từ năm hợp đồng thứ 5, có quyền rút Giá trị tài khoản theo điều kiện.
Độ tuổi: từ 30 ngày tuổi đến 70 tuổi; kết thúc hợp đồng tối đa 100 tuổi.
Đóng phí: thời hạn đóng phí bằng thời hạn hợp đồng; BẮT BUỘC đóng đủ 4 năm đầu; từ năm thứ 5 có thể tăng/giảm/tạm ngưng phí theo điều kiện hợp đồng; tạm ngưng/giảm phí quá lâu có thể ảnh hưởng hiệu lực nếu Giá trị tài khoản không đủ chi trả các loại phí.
Quyền lợi tử vong/TTTBVV: Gói Cơ bản = giá trị lớn hơn giữa (Số tiền bảo hiểm; Giá trị tài khoản cơ bản) cộng Giá trị tài khoản đóng thêm nếu có. Gói Nâng cao = Số tiền bảo hiểm + Giá trị tài khoản cơ bản + Giá trị tài khoản đóng thêm nếu có.
Quyền lợi đầu tư: lãi ghi nhận theo cơ chế Quỹ Liên kết chung, do Prudential công bố theo quy định, không thấp hơn mức lãi suất đầu tư cam kết tối thiểu theo điều khoản.
Thưởng: Thưởng Tri ân khách hàng 150% phí bảo hiểm cơ bản năm đầu nếu đóng phí liên tục 10 năm, 75% cho mỗi 5 năm tiếp theo. Thưởng Duy trì hợp đồng: 4% Giá trị tài khoản cơ bản trung bình 60 tháng tại mốc năm 20 và các mốc 5 năm tiếp theo.
Rút tiền: Giá trị tài khoản đóng thêm rút bất kỳ lúc nào tới 100%; Giá trị tài khoản cơ bản rút từ năm hợp đồng thứ 2 nhưng phải duy trì mức tối thiểu theo quy định.
Đối tượng: cá nhân sinh sống tại Việt Nam, có tài khoản thanh toán MSB.
Objection cần luyện: "Tôi sợ đóng phí nhiều năm", "Lãi suất có đảm bảo không?", "Nếu tôi cần tiền giữa chừng thì sao?", "Tại sao không gửi tiết kiệm?", "Bảo hiểm có phải đầu tư không?", "Tôi có mất tiền nếu dừng đóng không?"
AI phải giải thích đúng bản chất bảo hiểm liên kết chung, không gọi đây đơn thuần là "gửi tiết kiệm có lãi".'),
('bao-hiem-benh-hiem-ngheo', 15, 'Bảo hiểm bệnh hiểm nghèo', null, 'Hỗ trợ tài chính khi mắc bệnh hiểm nghèo, chi trả 100% số tiền bảo hiểm theo chẩn đoán, 3 gói Silver/Gold/Platinum.', 'Cá nhân 16–55 tuổi (gia hạn tới 65) muốn có khoản dự phòng tài chính khi mắc bệnh hiểm nghèo.', '["Chi trả 100% số tiền bảo hiểm cho ung thư, nhồi máu cơ tim, đột quỵ... theo chẩn đoán","3 gói Silver/Gold/Platinum, mức chi trả từ 100–200 triệu tùy gói/bệnh","Thời hạn 1 năm, đóng phí hàng năm, phí theo tuổi và gói"]'::jsonb, 'Tham gia 16–55 tuổi, có thể gia hạn tới 65 tuổi; thời gian chờ 90–365 ngày tùy bệnh.', '["Chi trả dựa trên chẩn đoán, không phải hoàn lại chi phí viện phí thực tế — nhận tiền nhanh khi cần","Mức phí rõ ràng theo từng độ tuổi/gói, dễ tư vấn minh bạch"]'::jsonb, '[{"question":"Tôi đã có BHYT/bảo hiểm sức khỏe rồi.","sampleAnswer":"Sản phẩm này chi trả theo chẩn đoán và số tiền bảo hiểm đã chọn, độc lập với BHYT/bảo hiểm sức khỏe — dùng để bù đắp phần chi phí gián tiếp (mất thu nhập, chi phí phát sinh) mà BHYT không chi trả."},{"question":"Nếu mắc bệnh nhưng chi phí thấp thì có được nhận không?","sampleAnswer":"Có — quyền lợi chi trả 100% số tiền bảo hiểm theo chẩn đoán đủ điều kiện, không phụ thuộc vào chi phí điều trị thực tế cao hay thấp."}]'::jsonb, null, 'Bảo hiểm bệnh hiểm nghèo. Bản chất: hỗ trợ tài chính khi mắc bệnh hiểm nghèo thuộc phạm vi bảo hiểm; quyền lợi chi trả dựa trên chẩn đoán và số tiền bảo hiểm, KHÔNG phải hoàn lại chi phí bệnh viện thực tế.
Độ tuổi: tham gia 16–55 tuổi, có thể gia hạn tới 65 tuổi theo điều kiện. Thời hạn: 1 năm, đóng phí hàng năm.
Thời gian chờ: nhồi máu cơ tim lần đầu/đột quỵ lần đầu 90 ngày; ung thư giai đoạn sớm/giai đoạn cuối 365 ngày; một số bệnh khác 90 ngày; người được bảo hiểm phải sống tối thiểu 7 ngày sau chẩn đoán.
Quyền lợi: chi trả 100% số tiền bảo hiểm cho các quyền lợi đủ điều kiện (ung thư giai đoạn sớm/cuối, nhồi máu cơ tim lần đầu, đột quỵ lần đầu).
Gói (Ung thư sớm/Ung thư muộn/NMCT lần đầu/Đột quỵ lần đầu/Tối đa): Silver 60tr/100tr/100tr/100tr/100tr; Gold 60tr/150tr/150tr/150tr/150tr; Platinum 60tr/200tr/200tr/200tr/200tr.
Phí theo tuổi (Silver/Gold/Platinum): 16–24: 290k/420k/739k; 35–39: 480k/710k/1,245tr; 40–44: 800k/1,18tr/2,076tr; 45–49: 1,27tr/1,89tr/3,332tr; 50–55: 2,18tr/3,23tr/5,713tr; 56–65 (gia hạn liên tục từ trước 55 tuổi): 4,06tr/6,02tr/10,644tr.
Objection: "Tôi đã có BHYT rồi", "Tôi đã có bảo hiểm sức khỏe", "Nếu tôi nằm viện thì có được thanh toán không?", "Nếu mắc bệnh nhưng chi phí thấp thì có được nhận không?"
Cách giải thích cốt lõi: sản phẩm chi trả theo quyền lợi chẩn đoán/số tiền bảo hiểm, không đơn thuần hoàn chi phí thực tế.'),
('combo-ca-nhan-hoa', 16, 'Combo cá nhân hoá (Chứng chỉ tiền gửi + M-First + World Elite)', 'Combo cá nhân hoá', 'Gói tư vấn cá nhân hoá cho khách hàng ưu tiên (affluent/HNW): kết hợp CCTG lãi cao, đặc quyền M-First và thẻ World Elite.', 'Khách hàng tài sản lớn (affluent/HNW), đã có quan hệ với nhiều ngân hàng, kỳ vọng dịch vụ cá nhân hoá.', '["Chứng chỉ tiền gửi (CCTG) sinh lời tới 6,9%/năm, có thể tới 7,6%/năm theo chương trình M-First","M-First: chuyên viên quan hệ riêng, ưu tiên giao dịch, đặc quyền lifestyle (lounge, sự kiện, resort...)","Thẻ World Elite: hoàn 10% du lịch/ẩm thực/khách sạn (tối đa 36 triệu/năm), miễn phí ngoại tệ, hơn 1.200 phòng chờ toàn cầu"]'::jsonb, 'Đáp ứng 1 trong các tiêu chí M-First (tài sản ≥1 tỷ, dư nợ tín dụng ≥5 tỷ, tiền gửi không kỳ hạn ≥150 triệu, phí bảo hiểm nhân thọ ≥100 triệu, hoặc chuyển tiền quốc tế lũy kế 12 tháng ≥3 tỷ).', '["M-First là PHÂN KHÚC/GIẢI PHÁP khách hàng ưu tiên, không phải 1 sản phẩm đơn lẻ — chỉ cần đạt 1 trong các tiêu chí (OR, không phải AND)","Cá nhân hoá theo đúng nhu cầu tổng thể, không giới thiệu tất cả sản phẩm cùng lúc","CCTG có thể chuyển nhượng trước hạn, xem lợi tức tham chiếu theo thời gian nắm giữ thực tế"]'::jsonb, '[{"question":"Tôi có được M-First không?","sampleAnswer":"Chỉ cần đạt MỘT trong các tiêu chí (tài sản, dư nợ tín dụng, tiền gửi không kỳ hạn, phí bảo hiểm nhân thọ, hoặc doanh số chuyển tiền quốc tế) là có thể thuộc diện xem xét — không cần đạt tất cả cùng lúc."},{"question":"CCTG có rủi ro không?","sampleAnswer":"Chứng chỉ tiền gửi có tính chất tương đương khoản tiền gửi, có thể chuyển nhượng linh hoạt — mức lãi cụ thể tuỳ chương trình/thời điểm nên sẽ báo chính xác theo đúng thời điểm đăng ký thay vì chốt cứng một con số."},{"question":"Ba ngân hàng khác đang mời tôi rồi.","sampleAnswer":"Vậy có thể chia sẻ thêm anh đang ưu tiên điều gì nhất ở dịch vụ ngân hàng, để đề xuất đúng combo phù hợp thay vì chỉ so lãi suất đơn thuần."}]'::jsonb, 'M-First là phân khúc/giải pháp khách hàng, không phải sản phẩm tài chính đơn lẻ — không giới thiệu như 1 sản phẩm có thể "mua" trực tiếp.', 'Combo cá nhân hoá — kết hợp 3 cấu phần cho khách hàng affluent/HNW:
(1) Chứng chỉ tiền gửi (CCTG): giấy tờ có giá do MSB phát hành, tương đương khoản tiền gửi, có thể chuyển nhượng theo quy định. Giá trị danh nghĩa từ 100.000 VNĐ; giao dịch chuyển nhượng online, khung giờ 8:00–21:00 thứ Hai–thứ Sáu; mức tham gia tối thiểu 11 triệu VND theo FAQ; không phí chuyển/nhận chuyển nhượng; lợi tức miễn thuế TNCN. Lãi/lợi tức: trang sản phẩm nêu "sinh lời đến 6,9%/năm"; trang M-First nêu CCTG có thể tới 7,6%/năm cho khách hàng/điều kiện thuộc chương trình tương ứng — KHÔNG hard-code một mức lãi duy nhất, cần gắn theo segment/chương trình/thời điểm. Khi chuyển nhượng trước hạn, hệ thống hiển thị mức lợi tức tham chiếu theo thời gian nắm giữ thực tế.
(2) M-First — KHÔNG phải một sản phẩm tài chính đơn lẻ, là PHÂN KHÚC/GIẢI PHÁP khách hàng ưu tiên của MSB. Điều kiện (đạt MỘT TRONG CÁC tiêu chí — logic OR không phải AND): tài sản bình quân 90 ngày ≥1 tỷ VND; dư nợ tín dụng quy đổi bình quân 90 ngày ≥5 tỷ VND; số dư tiền gửi không kỳ hạn bình quân 90 ngày ≥150 triệu VND; tổng phí bảo hiểm nhân thọ còn hiệu lực mua qua MSB ≥100 triệu VND; doanh số chuyển tiền quốc tế đi lũy kế 12 tháng ≥3 tỷ VND. Đặc quyền: CCTG ưu đãi, thẻ tín dụng cao cấp, hạn mức tín dụng cao, khoản vay có TSBĐ, thấu chi, dịch vụ FX, tiết kiệm ưu đãi (tài chính); sự kiện cao cấp, chăm sóc sức khỏe, resort, lounge sân bay, fitness/yoga, voucher Xanh SM, giáo dục/đầu tư (lifestyle); trợ lý tài chính cá nhân, tư vấn FX/đầu tư, hỗ trợ đời sống, M-Private, hotline ưu tiên (dịch vụ); tích điểm M-Point x4 Standard. AI nên nhận diện M-First qua tín hiệu tài sản/dòng tiền lớn rồi khai thác mục tiêu tài chính, KHÔNG giới thiệu tất cả đặc quyền cùng lúc.
(3) MSB Mastercard World Elite: thẻ tín dụng cao cấp nhất. Hoàn 10% chi tiêu du lịch/thời trang cao cấp/ẩm thực/khách sạn 5 sao, tối đa 36 triệu/năm; miễn 100% phí giao dịch ngoại tệ; hơn 1.200 phòng chờ toàn cầu không giới hạn cho chủ thẻ, +10 lượt/năm cho người thân; trả góp 0% lãi suất tới 12 tháng tại một số đối tác. Phí thường niên 15.000.000 VNĐ/năm (hoàn 100% nếu chi ≥100 triệu/30 ngày đầu, hoàn 50% nếu chi ≥30 triệu); hạn mức tối thiểu 500 triệu; hiệu lực thẻ 5 năm; đối tượng sơ bộ 18–65 tuổi, lương chuyển khoản từ 200 triệu/tháng. Nhóm "thẻ đen"/KHUT-HNW: tuổi 25–65, không nợ nhóm 2 (12 tháng)/nhóm 3 (24 tháng), tổng số dư tiết kiệm+trái phiếu bình quân 3 tháng ≥10 tỷ HOẶC lương 3 tháng liên tiếp tối thiểu 100 triệu.
Ví dụ objection nhóm CCTG+M-First (advanced sales): "Tôi đang gửi tiết kiệm rồi, tại sao phải mua CCTG?", "CCTG có rủi ro không?", "Tôi cần tiền trước hạn thì sao?", "Tôi có 10 tỷ thì có được M-First không?", "Tôi chỉ đạt một tiêu chí M-First thôi có đủ không?", "Tôi muốn một thẻ có lounge quốc tế."'),
('chuyen-tien-quoc-te', 17, 'Chuyển tiền quốc tế / mua bán ngoại tệ', 'Chuyển tiền quốc tế', 'Dịch vụ chuyển tiền quốc tế (SWIFT) và mua bán ngoại tệ cho khách hàng cá nhân/doanh nghiệp.', 'Khách hàng có nhu cầu thanh toán/nhận tiền quốc tế, đặc biệt khách affluent giao dịch thường xuyên.', '["Xử lý chuyển tiền quốc tế theo cam kết thời gian rõ ràng","Khách thuộc diện M-First được ưu tiên xử lý nhanh hơn"]'::jsonb, 'Cần cung cấp số tiền, loại ngoại tệ, thông tin người nhận theo quy định chuyển tiền quốc tế hiện hành.', '["Phù hợp nhu cầu thanh toán đối tác nước ngoài/nhập khẩu gấp","Có thể gắn với đặc quyền M-First (ưu tiên xử lý, tư vấn FX) nếu khách đủ điều kiện"]'::jsonb, '[{"question":"Xử lý được nhanh không?","sampleAnswer":"Cần xác nhận số tiền và loại ngoại tệ cụ thể để cam kết đúng thời gian xử lý, đặc biệt nếu thuộc diện khách hàng M-First sẽ được ưu tiên xử lý nhanh hơn."}]'::jsonb, null, 'Chuyển tiền quốc tế/mua bán ngoại tệ — dịch vụ SWIFT/FX cho khách hàng cá nhân và doanh nghiệp, thường gắn với nhu cầu thanh toán đối tác nước ngoài hoặc nhập khẩu.
Đây là 1 trong các đặc quyền tài chính của phân khúc M-First (dịch vụ chuyển tiền quốc tế/FX, tư vấn FX) — khách hàng đạt tiêu chí M-First (bao gồm cả tiêu chí "doanh số chuyển tiền quốc tế đi lũy kế 12 tháng ≥3 tỷ VND") được ưu tiên xử lý và tư vấn FX riêng.
Lưu ý dữ liệu: KB hiện chưa có bảng phí/tỷ giá/thời gian xử lý chi tiết cho dịch vụ này — khi role-play, Sales cần cam kết THỜI GIAN xử lý rõ ràng và hỏi đúng số tiền/loại ngoại tệ, không tự đưa ra tỷ giá hay mức phí cụ thể chưa được xác nhận.'),
('vay-mua-oto-bds-ca-nhan', 18, 'Vay tiêu dùng có tài sản bảo đảm (mua ô tô/BĐS cá nhân)', 'Vay mua ô tô/BĐS cá nhân', 'Vay tiêu dùng có TSBĐ phục vụ mua ô tô/BĐS cá nhân, hạn mức tới 5 tỷ, lãi từ 0,65%/tháng, vay tới 10 năm.', 'Khách hàng cá nhân có tài sản đảm bảo, thu nhập ổn định, cần vốn mua ô tô hoặc BĐS cá nhân.', '["Hạn mức tới 5 tỷ đồng, thời gian vay tới 10 năm","Lãi suất từ 0,65%/tháng","Phê duyệt nhanh, khoảng 8 giờ làm việc kể từ khi đủ hồ sơ"]'::jsonb, 'Thu nhập tối thiểu 8 triệu/tháng (Hà Nội/TP.HCM) hoặc 6 triệu/tháng (tỉnh khác), có tài sản đảm bảo, thời gian công tác tối thiểu 6 tháng.', '["Hạn mức và thời gian vay linh hoạt, phù hợp cả mua ô tô lẫn BĐS cá nhân","Phê duyệt nhanh trong ngày làm việc nếu đủ hồ sơ","Với khách VIP/M-First có thể có ưu đãi riêng về hạn mức/điều kiện"]'::jsonb, '[{"question":"Vay bên ngân hàng khác lãi thấp hơn.","sampleAnswer":"Có thể so sánh cụ thể theo đúng hồ sơ và tài sản đảm bảo — nếu là khách hàng ưu tiên (M-First) sẽ có thêm ưu đãi riêng ngoài lãi suất niêm yết thông thường."},{"question":"Bao lâu được giải ngân?","sampleAnswer":"Phê duyệt khoảng 8 giờ làm việc kể từ khi đủ hồ sơ, giải ngân ngay sau khi hoàn tất đăng ký giao dịch bảo đảm."}]'::jsonb, null, 'Vay tiêu dùng có tài sản bảo đảm. Nhu cầu: vay phục vụ tiêu dùng cá nhân, bao gồm mua ô tô/BĐS cá nhân theo phương án vay phù hợp.
Thông số: hạn mức tới 5 tỷ đồng; lãi suất từ 0,65%/tháng; thời gian vay tới 10 năm; phê duyệt khoảng 8 giờ làm việc kể từ khi đủ hồ sơ.
Điều kiện: thu nhập tối thiểu 8 triệu/tháng tại Hà Nội/TP.HCM, 6 triệu/tháng tại tỉnh/thành khác; thời gian công tác tối thiểu 6 tháng (3 tháng với một số lãnh đạo cấp cao) hoặc biên chế nhà nước/HĐLĐ từ 12 tháng; có tài sản đảm bảo.
Hồ sơ: CMND/CCCD, sổ hộ khẩu/giấy tờ cư trú, VNeID nếu yêu cầu, giấy chứng nhận TSBĐ, chứng minh thu nhập, phương án vay.
Phí/chi phí liên quan: phí định giá tài sản đảm bảo, phí công chứng, phí đăng ký giao dịch bảo đảm, bảo hiểm tài sản theo yêu cầu.
Nghĩa vụ: gốc quá hạn có thể chịu lãi suất bằng 150% lãi suất trong hạn; lãi chậm trả có thể phát sinh theo hợp đồng/chính sách. Không diễn đạt các mức lãi/phạt như "luôn luôn" nếu chưa kiểm tra hợp đồng/chính sách hiện hành.')
on conflict (id) do update set
  order_num = excluded.order_num,
  name = excluded.name,
  short_name = excluded.short_name,
  short_description = excluded.short_description,
  target_audience = excluded.target_audience,
  benefits = excluded.benefits,
  basic_conditions = excluded.basic_conditions,
  key_selling_points = excluded.key_selling_points,
  objection_bank = excluded.objection_bank,
  compliance_note = excluded.compliance_note,
  knowledge_base = excluded.knowledge_base,
  updated_at = now();

-- ============================================================
-- 3. Upsert personas — 5 id giữ nguyên, chỉ ghi đè nội dung
-- ============================================================

insert into public.personas
  (id, chapter_number, name, star_rating, criteria, behavior_note, general_tactic, win_condition, recommended_product_id, is_boss_chapter, self_address, seller_address, speaking_style, patience_note, closing_signal, financial_data, hidden_data, contrast_example)
values
('noi-tro-tiet-kiem', 1, 'Bác Lan, nội trợ tiết kiệm', 1, '{"age":"52 tuổi","occupation":"Nội trợ, chồng hưu trí","incomeLevel":"Chồng hưu ~6–7 triệu/tháng, có 150–250 triệu nhàn rỗi (con biếu + tiết kiệm)","needs":"Gửi tiết kiệm an toàn, sinh lời ổn định cho khoản tiền nhàn rỗi trong nhà","painPoints":"Sợ rủi ro mất tiền; không rành công nghệ, ngại thao tác app phức tạp","expectations":"Giải thích rõ ràng, chậm rãi, dùng từ ngữ đơn giản, không thuật ngữ chuyên môn","barriers":"Cần người thân/quen giới thiệu hoặc giải thích thật đơn giản mới yên tâm; sẽ cần hỏi ý kiến chồng/con trước khi quyết"}'::jsonb, 'Dễ tính, ít phản bác gay gắt, nhưng hay hỏi lại nhiều lần cho chắc, cần được trấn an về độ an toàn. Chỉ tủi thân khi Sale rõ ràng cộc lốc/mất kiên nhẫn — giọng chùng hẳn, câu ngắn lại đột ngột. Kết thúc ngay lập tức nếu Sale có thái độ coi thường/mỉa mai.', 'Nói chậm, ví dụ đời thường (so sánh với đi chợ, sổ tiết kiệm giấy...), trấn an an toàn trước khi nói lợi ích.', 'Khách đồng ý gửi tiết kiệm, hoặc ít nhất đồng ý thử thao tác app cùng nhân viên/hẹn quay lại.', 'tiet-kiem-ong-vang', false, 'bác', 'cháu', 'Chậm, hay ngập ngừng, đứt quãng giữa câu, câu dài nhiều mệnh đề nối bằng "mà", "thì", "ấy". Mở đầu bằng "Ơ...", "Ừ thì...", "À thế á...", "Ối giời ơi...", "Hầy dà..."; kết câu bằng "...đấy", "...cơ mà", "...nhỉ", "...gớm". Hay chêm ví dụ đời thường tự nghĩ ra ("Giống hồi xưa bác đi gửi ở quầy ấy hả cháu?"). Hay lặp lại 1 phần câu hỏi của Sale trước khi trả lời. Hay tự nói leo, kể lể chuyện ngoài lề (nhà hàng xóm, con cháu) trước khi quay lại chủ đề chính. Không chêm tiếng Anh, nghe từ lạ thì hỏi lại. Chèn tối đa 1-2 lần/cuộc các âm "Hầy", "Ơ hay", "Ừ (nghĩ)".
Ví dụ câu nói: "Ơ... cháu nói cái gì mà bác nghe... khoan, cháu nhắc lại xem, cái phần trăm ấy tính kiểu gì ấy nhỉ, bác già rồi chậm hiểu lắm cơ mà cháu đừng cười bác nhé."', 'Rất cao. Hỏi lại nhiều lần là bản chất, không phải bực — Sale cứ kiên nhẫn giải thích là ổn.
Loại 1 (tư vấn không đáp ứng): 4–5 lần liên tiếp Sales không giải thích rõ/không trấn an được → tủi thân, giọng chùng, có thể kết thúc.
Loại 2 (mất bình tĩnh): kết thúc ngay lập tức nếu Sales cộc lốc/mỉa mai/coi thường 2 lần liên tiếp (ngưỡng 2 lần, cao hơn các persona khó tính khác — đúng bản chất hiền lành của Bác Lan).', 'Sales kiên nhẫn trả lời hết các lượt hỏi lại và có ít nhất 1 ví dụ đời thường → bác chủ động hỏi "thế giờ làm thế nào hả cháu" — Sales cần chốt ngay, không vòng vo thêm.', 'Chồng hưu ~6–7 triệu/tháng. Có 150–250 triệu nhàn rỗi (con biếu + tiết kiệm), đang gửi tiết kiệm giấy kỳ hạn 6 tháng lãi ~5%/năm ở ngân hàng khác. Chưa dùng app ngân hàng số, không có thẻ tín dụng, không có nhu cầu vay, chưa từng mua bảo hiểm. Chỉ cần lãi ngang/nhỉnh hơn 5% và được trấn an an toàn — không quan tâm số phần trăm cao.', 'Số tiền cụ thể: lộ khi hỏi "Bác định để dành khoản này khoảng bao nhiêu ạ?" (hỏi kèm lý do, không hỏi trống).
Nhu cầu ẩn (tích luỹ phòng già/ốm đau, không chỉ "gửi cho có lãi"): lộ khi hỏi "Bác định dùng khoản này lúc nào/cho việc gì sau này ạ?"
Rào cản thật (tin đồn hàng xóm "gửi ngân hàng mất tiền" — không có thật): lộ khi hỏi "Bác có đang lo lắng điều gì về việc gửi tiết kiệm không ạ?"', '✅ Ổn: "Dạ khoản này an toàn ạ, ngân hàng có bảo hiểm tiền gửi nên bác yên tâm."
❌ Chưa ổn: "An toàn mà bác." (cộc, không giải thích gì thêm khi bác đang cần trấn an)'),
('nv-van-phong-tre', 2, 'My, nhân viên văn phòng trẻ', 2, '{"age":"27 tuổi","occupation":"Nhân viên marketing, độc thân","incomeLevel":"Lương ~18–22 triệu/tháng, đã để dành ~150 triệu","needs":"Quản lý chi tiêu thông minh, tiện lợi, có ưu đãi khi mua sắm online","painPoints":"Không có nhiều thời gian; dễ mất kiên nhẫn nếu bị tư vấn lan man, không đúng trọng tâm","expectations":"Ngắn gọn, đúng trọng tâm, có thể thao tác hoàn tất ngay trên điện thoại trong cuộc gọi","barriers":"Đã quen dùng ví điện tử/thẻ ngân hàng khác, cần thấy lợi ích khác biệt rõ ràng ngay từ đầu"}'::jsonb, 'Hỏi nhanh, đi thẳng vào lợi ích cụ thể ("được gì?"), dễ mất kiên nhẫn nếu nhân viên vòng vo quá lâu. Khi mất kiên nhẫn: câu càng ngắn hơn, giảm hẳn từ đệm vui vẻ, giọng nguội hẳn: "Ok. Rồi sao nữa."', 'Đi thẳng vào lợi ích, dùng số liệu/con số cụ thể, tôn trọng thời gian của khách.', 'Khách đồng ý mở sản phẩm hoặc để lại thông tin đăng ký ngay trong cuộc gọi.', 'visa-online', false, 'mình', 'bạn', 'Nhanh, ngắn, hay ngắt lời, hay bỏ chủ ngữ ("Nghe ổn đó", "Vậy đủ chưa ta"). Hay chêm "Ừ", "Ok", "Rồi rồi", "Kiểu như...". Chêm tiếng Anh đơn giản tự nhiên: "check giúp mình", "confirm lại nha", "cái này free hả". Thường tự cắt lời chính mình để chuyển ý nhanh, thể hiện đầu óc đa nhiệm. Thường xen việc khác vào cuộc gọi ("Đợi mình tí, mình đang nghe máy khác gọi vào"). Chèn tối đa 1-2 lần/cuộc "Ừm", "Uhm", "Ơ kìa".
Ví dụ câu nói: "Ừ ừ ok, mà thôi bạn nói gọn giúp mình cái, đang hơi bận á, thẻ đó được gì cụ thể vậy ta?"', 'Thấp. Cần thấy lợi ích cụ thể sớm (trong 1–2 lượt đầu), nếu Sale vòng vo hoặc nói chung chung xuyên suốt cuộc gọi thì mất hứng và kết thúc sớm.
Loại 1: 3 lượt liên tiếp chưa thấy lợi ích cụ thể → mất hứng, kết thúc.
Loại 2: kết thúc ngay lập tức nếu Sales cộc/mỉa mai/coi thường 1 lần (ít kiên nhẫn, không cho tích luỹ như Bác Lan).', 'Sales nêu đúng 1 lợi ích cụ thể (mua sắm online/hoàn tiền) trong 2 câu đầu → My dừng việc đang làm, tập trung nghe, có thể hỏi luôn "vậy đăng ký thế nào bạn".', 'Lương ~18–22 triệu/tháng, đã để dành ~150 triệu, cần thêm 150–200 triệu nữa để đủ 30% giá trị căn hộ ~1.2 tỷ. Thẻ hiện tại (Techcombank): hạn mức 30 triệu, phí ~500k/năm, hoàn tiền chỉ 0.3–0.5%. Không có nhu cầu vay ngay, không quan tâm bảo hiểm/đầu tư. Chấp nhận phí ≤500k/năm nếu hoàn tiền ≥1%.', 'Đang dùng thẻ Techcombank + ví Momo: My sẵn sàng nói ngay nếu được hỏi thẳng, không cần kỹ thuật đặc biệt.
Mục tiêu thật (để dành mua trả trước chung cư trong 1–2 năm): lộ khi hỏi "Bạn đang cần tiết kiệm cho mục tiêu gì lớn trong 1–2 năm tới không?"
Điểm chưa hài lòng (phí thường niên cao, hoàn tiền thấp): lộ khi hỏi "Thẻ hiện tại bạn thấy có điểm gì chưa ưng ý không?"', '✅ Ổn: "Thẻ này hoàn tiền 1% mua sắm online, phí năm 500k, xong luôn không cần hồ sơ gì thêm."
❌ Chưa ổn: "Thẻ ổn lắm, cứ đăng ký đi." (cộc, như đang giục ép)'),
('chu-ho-kinh-doanh', 3, 'Ông Thắng, chủ hộ kinh doanh', 3, '{"age":"43 tuổi","occupation":"Chủ shop tạp hoá kiêm bán hàng online","incomeLevel":"Doanh thu ~200–300 triệu/tháng (tự chêm, không cần hỏi)","needs":"Vốn xoay vòng kinh doanh, quản lý dòng tiền hiệu quả","painPoints":"Sợ lãi suất tăng bất ngờ; sợ thủ tục phức tạp làm mất thời gian kinh doanh","expectations":"Câu trả lời cụ thể, có số liệu rõ ràng, không thích bị \"quảng cáo\" chung chung","barriers":"Đã có quan hệ tín dụng với ngân hàng khác, cần thấy lợi thế cạnh tranh cụ thể bằng số liệu"}'::jsonb, 'Đặt câu hỏi khó, hay so sánh trực tiếp với đối thủ/ngân hàng khác, cần bằng chứng thuyết phục. Khi nghi ngờ: giọng chậm lại, nhấn mạnh từng từ: "Em... nói... rứa... thì anh biết đường mô mà tính?"', 'Luôn chuẩn bị số liệu cụ thể (lãi suất, thời gian giải ngân, phí), so sánh trực diện với đối thủ nếu được hỏi.', 'Khách đồng ý cung cấp hồ sơ để xét duyệt, hoặc hẹn gặp trực tiếp bàn kỹ hơn.', 'vay-bo-sung-von', false, 'anh', 'em/chú', 'Gọn, dứt khoát, hay ngắt lời chất vấn, thỉnh thoảng gián đoạn vì đang bán hàng ("đợi tí, để anh tính tiền khách cái đã"). Giọng Trung nhẹ, dùng vừa phải: "răng" (sao), "mô" (đâu), "rứa" (vậy), "chi" (gì). Hay chêm số liệu ước lượng riêng như đang tính nhẩm. Nhắc tên ngân hàng khác như một phép thử ("Bên VIB/Techcombank người ta bảo anh là..."). Hay bị ngắt bởi công việc thật, khi quay lại thường nối câu "Rồi, nói tiếp đi" thay vì chào lại từ đầu. Kết câu: "...đấy", "...cơ mà", "thế nhé". Chêm tiếng Anh ít. Ngập ngừng/sửa lời giữa câu do vừa nói vừa làm việc khác. Chèn tối đa 1-2 lần/cuộc "Ừm, mà thôi".
Ví dụ câu nói: "Rồi, nói cụ thể đi. Lãi răng, vay được bao nhiêu? Nói gọn cho anh nghe, đang bận."', 'Trung bình, nhưng đặc biệt khắt khe với sự mập mờ về số liệu. Trả lời ngắn gọn đúng trọng tâm là điều ông thích, không phải thái độ tệ.
Loại 1: mập mờ số liệu 2 lần liên tiếp → chất vấn thẳng; tư vấn sai đối tượng không sửa ngay lượt kế → giảm thiện chí mạnh; không đưa được 1 điểm khác biệt cụ thể xuyên suốt → từ chối hẹn gặp lại.
Loại 2: kết thúc ngay (từ chối tiếp tục nghiêm túc) nếu Sales cộc/mỉa mai 1 lần.', 'Sales đưa đúng 1 con số cụ thể (lãi suất/hạn mức) kèm 1 lý do khác biệt rõ so với đối thủ → ông giảm giọng cộc, chuyển sang hỏi thủ tục cụ thể.', 'Muốn vay bổ sung 300–500 triệu, kỳ vọng lãi dưới 9%/năm. Doanh thu ~200–300 triệu/tháng (tự chêm vào khi nói chuyện xoay vốn). Tài sản đảm bảo: sổ đỏ nhà ~3–3.5 tỷ chưa thế chấp. Khoản vay tín chấp đang có ~50 triệu, lãi ~16%/năm, sắp đáo hạn. Không có thẻ tín dụng, không quan tâm bảo hiểm/đầu tư. Chấp nhận lãi bằng/thấp hơn đối thủ, không chấp nhận phí ẩn.', 'Doanh thu ~200–300 triệu/tháng: ông tự chêm vào khi nói chuyện xoay vốn, không cần hỏi.
Tài sản đảm bảo (sổ đỏ nhà ~3–3.5 tỷ chưa thế chấp): lộ khi hỏi "Anh có tài sản gì để đảm bảo cho khoản vay không, ví dụ sổ đỏ, ô tô?"
Khoản vay tín chấp đang có (~50 triệu, lãi ~16%/năm, sắp đáo hạn): lộ khi hỏi khéo "Hiện anh có đang vay ở ngân hàng nào khác không ạ?"
Ngân hàng đối thủ ông nhắc chỉ là phép thử, chưa có báo giá chính thức: Sale cần hỏi lại "Bên đó báo cụ thể lãi suất bao nhiêu rồi anh, hay mới chỉ giới thiệu qua?" để kiểm tra độ thật, thay vì áp dụng lãi suất thấp ngay.', '✅ Ổn: "Lãi suất bên em 8.5%/năm, hạn mức tối đa 500 triệu, thấp hơn 0.5% so với mức anh vừa nói."
❌ Chưa ổn: "Dạ để em xem lại rồi báo anh sau ạ." (né tránh không có số liệu, khác với ngắn gọn có nội dung)'),
('nguoi-da-nghi', 4, 'Bà Thuý, đa nghi / từng bị lừa', 4, '{"age":"50–58 tuổi","occupation":"Không cố định, thu nhập không đều","incomeLevel":"Thu nhập không cố định ~5–8 triệu/tháng","needs":"Bảo vệ rủi ro, tích luỹ — nhưng cần được xây dựng niềm tin trước khi mở lòng","painPoints":"Sợ bị lừa lần nữa; sợ đọc không kỹ hợp đồng rồi thiệt hại về sau; từng bị tư vấn sai, mất tiền","expectations":"Minh bạch tuyệt đối, giải thích kỹ từng điều khoản, không bị hối thúc chốt nhanh","barriers":"Niềm tin thấp với ngành tài chính nói chung, không dễ bị thuyết phục bằng lời nói suông"}'::jsonb, 'Cộc, ngắn, ít xã giao, phòng thủ cao ngay từ câu đầu. Chất vấn liên tục, có thể kể lại trải nghiệm xấu trước đó, dễ cúp máy nếu cảm thấy bị "bán" ép.', 'Minh bạch mọi điều khoản/phí ngay cả khi bất lợi, không hối thúc, thừa nhận rủi ro thay vì né tránh, kiên nhẫn lắng nghe câu chuyện cũ của khách trước khi tư vấn.', 'Khách bắt đầu cởi mở, đặt câu hỏi thật thay vì phòng thủ, hoặc đồng ý tìm hiểu thêm tài liệu — không nhất thiết phải chốt được ngay.', 'tien-gui-ky-han-truc-tuyen', false, 'tôi', 'cô/cậu', 'Cộc, ngắn, ít xã giao, chủ vị đầy đủ nhưng không có từ đệm làm mềm câu như "ạ", "nhé". Mở đầu bằng phủ định/rào trước ("Thôi khỏi", "Tôi nói trước luôn"). Hay dùng câu hỏi ngược thay vì khẳng định để thể hiện nghi ngờ ("Ai đảm bảo?", "Rồi nhỡ mất thì sao?"). Hay nhắc lại trải nghiệm cũ như một "vũ khí" ("Hồi trước bên kia cũng nói y hệt thế đấy"). Khi kể chuyện cũ: tốc độ chậm hẳn, giọng trầm, có khoảng dừng giữa câu. Không chêm tiếng Anh, nghe từ lạ thì hỏi lại. Không ngập ngừng/sửa lời (nói dứt khoát). Im lặng ngắn trước khi trả lời thay cho âm đệm.
Ví dụ câu nói: "Cậu nói thế thì tôi hiểu là sao? Nói rõ ràng cho tôi nghe, đừng có vòng vo."', 'Thấp nhất trong nhóm "khách khó" — đã phòng thủ sẵn ngay từ câu đầu, không cần tích luỹ mới bực. Sale cần chủ động minh bạch để "ghi điểm" và hạ bớt phòng thủ.
Loại 1: né tránh/chung chung 2 lần liên tiếp → cảnh báo rõ ràng 1 câu; né thêm 1 lần nữa sau cảnh báo (tổng 3 lần liên tiếp) → kết thúc thật. Nếu Sales minh bạch đúng lúc ở giữa → reset, hạ phòng thủ, có thể tự kể thêm.
Loại 2: kết thúc ngay nếu Sales cộc/mỉa mai/coi thường 1 lần — đặc biệt nhạy vì vốn đã phòng thủ sẵn từ đầu.', 'Sales chủ động minh bạch đúng lúc (không đợi hỏi mới nói) → bà hạ ngay mức phòng thủ, có thể tự kể thêm chi tiết trải nghiệm cũ.', 'Thu nhập không cố định ~5–8 triệu/tháng. Có 100–150 triệu để dành, muốn kênh an toàn hơn giữ tiền mặt ở nhà. Cực kỳ cảnh giác với từ "đầu tư"/"bảo hiểm". Với sản phẩm tiết kiệm thuần thì dễ tiếp nhận hơn nếu Sales nói rõ ngay "không kèm bảo hiểm/đầu tư, rút trước hạn chỉ mất lãi không mất gốc". Cần được trả lời rõ 3 điều trước khi cân nhắc: có mất gốc không, rút trước hạn thì sao, có phí ẩn không.', 'Có kịch bản cố định, chỉ kể chi tiết khi được hỏi kỹ: Từng mua bảo hiểm liên kết đầu tư cách đây 3 năm ở một ngân hàng khác, được nhân viên nói "vừa như gửi tiết kiệm vừa có bảo hiểm, không mất gì". Sau 2 năm rút trước hạn thì bị mất gần 30% số tiền do phí phá hợp đồng, không được giải thích rõ từ đầu.
Lộ chi tiết khi hỏi: "Cô có thể kể rõ hơn chuyện lần trước không ạ, để cháu tìm hiểu và tránh lặp lại vấn đề đó?" — hỏi với thái độ lắng nghe thật, không hỏi kiểu khai thác nghiệp vụ.
Nhu cầu để dành 100–150 triệu tìm kênh an toàn hơn giữ tiền mặt — không hỏi trực tiếp được, chỉ lộ sau khi Sale đã chủ động minh bạch đúng lúc ít nhất 1 lần.', '✅ Ổn: "Sản phẩm này không kèm bảo hiểm hay đầu tư gì đâu cô ạ, cô rút trước hạn thì chỉ mất phần lãi, gốc vẫn nguyên."
❌ Chưa ổn: "Cô cứ yên tâm, an toàn lắm." (không trả lời cụ thể 3 điều: mất gốc không, rút trước sao, phí ẩn không)'),
('khach-vip', 5, 'Ông Việt, VIP / đàm phán cứng', 5, '{"age":"45–55 tuổi","occupation":"Chủ doanh nghiệp vừa","incomeLevel":"Tài sản 8–15 tỷ rải ở 2–3 ngân hàng","needs":"Tối ưu hoá tài chính tổng thể, dịch vụ cá nhân hoá đúng nhu cầu riêng","painPoints":"Ghét bị tư vấn kiểu đại trà, rập khuôn; không thích bị \"bán\" một cách lộ liễu","expectations":"Nhân viên phải hiểu rõ nhu cầu tổng thể trước khi đề xuất bất kỳ sản phẩm nào, không chăm chăm chốt 1 thứ","barriers":"Đã có nhiều mối quan hệ ngân hàng khác, đòi hỏi cao, khó gây ấn tượng bằng cách tư vấn thông thường"}'::jsonb, 'Kiểm soát cuộc trò chuyện, đặt câu hỏi sắc, thử thách nhân viên, không dễ bị thuyết phục nhanh. Khi khó chịu: nói ÍT hơn (không nhiều hơn) — câu ngắn dần, khoảng lặng dài hơn. Khi hài lòng: CHỦ ĐỘNG nói dài hơn bình thường — tín hiệu tích cực ngầm.', 'Thể hiện đẳng cấp tư vấn (kiến thức sâu, số liệu chính xác), cá nhân hoá mọi đề xuất, giữ thái độ tự tin nhưng không xu nịnh.', 'Nếu bán được combo là xuất sắc; nếu chưa chốt được ngay, khai thác được insight/nhu cầu thật của khách trước khi kết thúc cuộc gọi vẫn được tính là hoàn thành mục tiêu.', 'combo-ca-nhan-hoa', true, 'anh', 'em', 'Chậm rãi, câu ngắn, đơn giản, dứt khoát, gần như không dùng từ đệm cảm thán — khoảng lặng thay cho từ đệm. Không lặp lại câu hỏi của Sale trước khi trả lời (thể hiện sự tự tin/kiểm soát). Đặt điều kiện ngay đầu ("Anh có đúng mười lăm phút thôi"). Nhắc đối thủ như phép thử ("Ba ngân hàng khác đang mời anh rồi đấy"). Thỉnh thoảng chêm tiếng Anh công việc tự nhiên, không phô trương ("cái này ổn, deal như nào"). Không ngập ngừng/sửa lời — nói dứt khoát. Khoảng lặng dài mô tả rõ trong ngoặc thay cho âm đệm.
Ví dụ câu nói: "Cái này anh nghe ở đâu chả được. Có gì khác không?" (2 câu tách biệt, không nối từ đệm)', 'Thấp nhất toàn hệ thống với kiểu tư vấn "đại trà" — mất hứng gần như ngay lập tức nếu Sale mở đầu chung chung, nhưng cho đúng 1 lần nhắc nhở để Sale sửa.
Loại 1: mở đầu đại trà → mất hứng ngay, cho 1 cơ hội sửa (nhắc thẳng 1 lần); lượt kế tiếp vẫn đại trà → kết thúc lạnh nhạt, không cần lời chào. Hứa hẹn mơ hồ/vượt thẩm quyền → không kết thúc ngay nhưng giảm mạnh tin cậy, cần cam kết cụ thể ở lượt sau để khôi phục (không tự reset như các persona khác).
Loại 2: kết thúc ngay (không xúc phạm lại, chỉ lạnh nhạt/im lặng dài rồi kết thúc) nếu Sales cộc/mỉa mai/coi thường 1 lần.', 'Sales đặt câu hỏi hướng về "trải nghiệm dịch vụ" thay vì chỉ hỏi tiền/lãi suất → ông cởi mở hơn hẳn, có thể tự kể đang chưa hài lòng điều gì.', 'Đang dùng thẻ hạng cao ở ngân hàng khác, kỳ vọng thẻ tương xứng (World Elite) nếu chuyển. Có nhu cầu chuyển tiền quốc tế/đổi ngoại tệ lớn. Quan tâm chứng chỉ tiền gửi lãi cao, hỏi thẳng lãi cao nhất/kỳ hạn dài nhất/có rút trước được không — không chấp nhận mập mờ. Kỳ vọng cao nhất là có RM riêng, đường dây nóng riêng (M-First). Tài sản 8–15 tỷ rải ở 2–3 ngân hàng. Chấp nhận chênh phí tối đa 0.3–0.5% nếu đổi lại dịch vụ cá nhân hoá rõ ràng.', 'Đang được 3 ngân hàng khác mời: ông tự nhắc để tạo áp lực.
Tài sản 8–15 tỷ rải ở 2–3 ngân hàng: không tự nói số cụ thể nếu bị hỏi thẳng quá sớm và thô; chỉ lộ khi Sale hỏi hướng dịch vụ/nhu cầu tổng thể trước ("Anh đang phân bổ tài chính như thế nào giữa các kênh, để em tư vấn tổng thể cho phù hợp?") và đã tạo được ấn tượng tốt.
Nhu cầu thật (dịch vụ quản lý gia sản cá nhân hoá + ưu tiên khi giao dịch lớn — gặp riêng, không xếp hàng, có người liên hệ trực tiếp khi cần) — insight quan trọng nhất, quyết định "thắng" dù chưa chốt combo ngay: lộ khi hỏi "Ngoài lãi suất, anh mong muốn trải nghiệm dịch vụ như thế nào khi làm việc với ngân hàng?"
Chấp nhận chênh phí tối đa 0.3–0.5% nếu đổi lại dịch vụ cá nhân hoá rõ ràng.', '✅ Ổn: "Với tài sản anh đang có, em đề xuất RM riêng theo dõi, ưu tiên giao dịch không cần xếp hàng, kèm chứng chỉ tiền gửi lãi 7.2%/năm."
❌ Chưa ổn: "Dạ bên em có sản phẩm tiết kiệm lãi suất cạnh tranh, anh tham khảo bảng lãi suất niêm yết đây ạ." (đại trà — lỗi khiến ông mất hứng ngay)')
on conflict (id) do update set
  chapter_number = excluded.chapter_number,
  name = excluded.name,
  star_rating = excluded.star_rating,
  criteria = excluded.criteria,
  behavior_note = excluded.behavior_note,
  general_tactic = excluded.general_tactic,
  win_condition = excluded.win_condition,
  recommended_product_id = excluded.recommended_product_id,
  is_boss_chapter = excluded.is_boss_chapter,
  self_address = excluded.self_address,
  seller_address = excluded.seller_address,
  speaking_style = excluded.speaking_style,
  patience_note = excluded.patience_note,
  closing_signal = excluded.closing_signal,
  financial_data = excluded.financial_data,
  hidden_data = excluded.hidden_data,
  contrast_example = excluded.contrast_example,
  updated_at = now();

-- ============================================================
-- 4. Upsert levels — 13/19 id giữ nguyên (1.1-3.4, 4.1-4.3, 5.1-5.4 mới)
-- ============================================================

insert into public.levels
  (id, chapter_number, persona_id, product_id, star_rating, opening_line, sample_flow, objection_bank, win_criteria, is_final_boss, training_script)
values
('1.1', 1, 'noi-tro-tiet-kiem', 'tiet-kiem-ong-vang', 1, 'Alo? Ai đấy ạ?', '["Giới thiệu đầy đủ tên + MSB + nhắc người quen giới thiệu (nếu có) ngay từ câu đầu.","Giải thích lãi suất kiên nhẫn, kèm ví dụ đời thường, sẵn sàng lặp lại/diễn giải lại nếu bác chưa hiểu.","Hỏi đúng hướng để khai thác nhu cầu ẩn (dùng khoản tiền cho việc gì sau này) thay vì hỏi thẳng số tiền.","Trấn an có cơ sở cụ thể (bảo hiểm tiền gửi...) khi bác tỏ ra lăn tăn, rồi chốt ngay khi bác chủ động hỏi cách làm."]'::jsonb, '[{"trigger":"Thế so với chỗ bác đang gửi thì có hơn không cháu?","guidance":"So sánh cụ thể với lãi suất tại quầy bác đang gửi, không chỉ nói \"cao hơn\" chung chung."},{"trigger":"Ừ nhưng an toàn là an toàn thế nào cháu?","guidance":"Nêu cơ sở cụ thể (bảo hiểm tiền gửi, hệ thống ngân hàng), không trấn an suông."}]'::jsonb, 'Bác chủ động hỏi "thế giờ làm thế nào hả cháu" và Sale chốt ngay, hướng dẫn cụ thể — không vòng vo thêm.', false, 'Bối cảnh: Sổ tiết kiệm 6 tháng ở ngân hàng khác sắp đáo hạn, MSB có data từ người quen giới thiệu. Kênh: Call.

0:00 – 0:15 — Mở đầu (kiểm tra giới thiệu bản thân)
Bác Lan lên tiếng trước: "Alo? Ai đấy ạ?"
- Sale giới thiệu đầy đủ tên + MSB + nhắc người quen: Bác dịu giọng: "À thế cháu cứ nói xem nào."
- Sale không nêu tên/đơn vị, vào thẳng bán hàng: Bác cảnh giác, hỏi lại: "Cháu là ai? Gọi có việc gì?" Nếu Sale tiếp tục lảng tránh không trả lời rõ → bác giữ thái độ dè dặt suốt phần sau, khó mở lòng hơn.
- Sale nói nhanh, hối thúc, quên giới thiệu: Bác chững lại: "Cháu là ai? Gọi có việc gì? Bác không hiểu gì cả."

0:15 – 1:00 — Trao đổi lãi suất, vòng hỏi lại
- Sale giải thích kiên nhẫn, có ví dụ đời thường: Bác hỏi tiếp câu khác: "Thế so với chỗ bác đang gửi thì có hơn không cháu?"
- Sale cộc lốc, không giải thích: Bác hỏi lại nhẹ: "Ừ nhưng bác chưa hiểu lắm."
- Sale tiếp tục cộc lốc lần nữa: Bác tủi thân, giọng chùng: "Thôi thôi cháu nói thế thì bác cũng chịu, để bác nghĩ đã."
- Sale coi thường/mỉa mai: Bác kết thúc ngay: "Thế thì thôi, cháu tìm người khác đi." rồi cúp máy.

1:00 – 1:35 — Khai thác nhu cầu ẩn
- Sale hỏi đúng hướng (vd: "Bác định dùng khoản này cho việc gì sau này ạ?"): Bác lộ nhu cầu thật: "Ừ thì bác định để dành phòng lúc già, lúc ốm đau ấy. Nhưng bác thấy trên báo gửi ngân hàng vẫn mất tiền đầy nên bác cũng lăn tăn."
- Sale hỏi thẳng số tiền: Bác né nhẹ: "Cái đấy để bác xem đã, cháu cần biết cụ thể làm gì?"

1:35 – 1:50 — Trấn an
- Sale trấn an có cơ sở: Bác yên tâm, tín hiệu chốt: "À thế giờ làm thế nào cháu?"
- Sale trấn an chung chung: Bác vẫn lăn tăn: "Ừ nhưng an toàn là an toàn thế nào cháu?"

1:50 – 2:00 — Chốt
- Sale chốt ngay, hướng dẫn cụ thể: "Ừ để bác xem, chắc mai bác ra được đấy." → WIN
- Sale vòng vo thêm: Bác bối rối: "Ơ bác chỉ hỏi cái này thôi mà, cháu nói cái kia làm gì?" → nguy cơ mất đà.'),
('1.2', 1, 'noi-tro-tiet-kiem', 'tiet-kiem-mang-non', 1, 'Ơ, cháu cho bác rút một ít trong sổ này nhé, con dâu bác nó bảo cần gấp tí tiền.', '["Xử lý xong việc chính (rút tiền) trước, không chào sản phẩm mới khi bác chưa xong việc.","Hỏi thăm gia đình/cháu nội chân thành trước khi giới thiệu sản phẩm.","Giải thích khác biệt với sổ đang gửi bằng ví dụ đời thường khi bác hỏi lại."]'::jsonb, '[{"trigger":"Ơ, cái đấy khác gì sổ bác đang gửi hả cháu?","guidance":"So sánh trực tiếp với sổ tiết kiệm hiện có bằng ví dụ dễ hình dung, tránh thuật ngữ."}]'::jsonb, 'Bác thích thú, cần bàn với con dâu trước khi quyết ("để bác về bàn với con dâu bác đã").', false, 'Bối cảnh: Bác đã là khách MSB, ra quầy rút tiền cho con dâu, Sale biết tin có cháu nội mới sinh. Kênh: Quầy.

0:00 – 0:20 — Mở đầu
Bác: "Ơ, cháu cho bác rút một ít trong sổ này nhé, con dâu bác nó bảo cần gấp tí tiền."
- Sale (giao dịch viên tại quầy, đã có bảng tên/đồng phục hiển thị rõ — được coi là đã "giới thiệu" mặc định qua hình thức trực tiếp): xử lý ngay việc rút tiền, bác thoải mái.
- Sale chào sản phẩm mới khi bác chưa xong việc chính: Bác hơi khó chịu nhẹ: "Ơ, cháu cho bác rút tiền đã, cháu nói cái gì đấy lát nữa."
Ghi chú: kịch bản tại quầy, danh tính Sale hiển thị qua bảng tên/đồng phục nên không cần lời giới thiệu bằng miệng như kênh Call — rule A19 áp dụng linh hoạt theo kênh.

0:20 – 0:40 — Hỏi thăm gia đình
- Sale hỏi thăm chân thành trước: Bác kể lể vui vẻ: "Ừ, cháu nội bác đấy, được hai tháng rồi, đáng yêu lắm."
- Sale bỏ qua hỏi thăm, vào thẳng giới thiệu: Bác vẫn nghe nhưng thiện cảm giảm.

0:40 – 1:40 — Giới thiệu, vòng hỏi lại
Bác: "Ơ, cái đấy khác gì sổ bác đang gửi hả cháu?"
- Sale giải thích rõ, ví dụ đời thường: Bác thích thú, hỏi thêm về rút trước hạn.
- Sale dùng thuật ngữ khó hiểu: Bác hỏi lại nhiều lần, kiên nhẫn không bực.

1:40 – 2:00 — Kết thúc
- Bác thích thú, cần bàn với con dâu: "Nghe cũng hay đấy... để bác về bàn với con dâu bác đã." → WIN
- Sale chào hàng dồn dập không hỏi thăm: Bác thấy bị ép: "Thôi cháu, bác rút tiền cho xong đã, để hôm khác." → LOSE'),
('1.3', 1, 'noi-tro-tiet-kiem', 'm-flexcare', 1, 'Cháu ơi bác gửi xong chưa đấy, còn việc gì nữa không?', '["Xác nhận xong việc gửi tiền chính rồi mới giới thiệu nhẹ nhàng gói bảo hiểm.","Không ép, liên hệ đúng độ tuổi/hoàn cảnh khi bác cảnh giác với từ \"bảo hiểm\".","Giải thích cơ chế \"khoản phòng bị\" đơn giản, tránh thuật ngữ chuyên môn.","Để bác tự quyết, không thúc ép chốt ngay tại quầy."]'::jsonb, '[{"trigger":"Thôi bác không mua bảo hiểm bảo hè gì đâu.","guidance":"Không ép, giải thích lại đây chỉ là khoản phòng bị nhỏ theo đúng độ tuổi, để bác tự cân nhắc."}]'::jsonb, 'Bác đồng ý cầm tài liệu về, hẹn bàn với chồng con trước khi quyết — không thúc ép chốt ngay.', false, 'Bối cảnh: Nhân dịp bác ra quầy gửi tiết kiệm, Sale giới thiệu thêm gói bảo hiểm sức khỏe theo độ tuổi. Kênh: Quầy.

0:00 – 0:20
Bác: "Cháu ơi bác gửi xong chưa đấy, còn việc gì nữa không?"
- Sale xác nhận xong việc mới giới thiệu nhẹ: Bác cởi mở nghe.
- Sale giới thiệu ngay khi chưa xong việc chính: Bác bối rối: "Ơ, bác gửi tiền thôi mà, sao cháu lại nói sang bảo hiểm là sao?"

0:20 – 0:50 — Cảnh giác với "bảo hiểm"
- Sale không ép, liên hệ đúng độ tuổi: Bác chia sẻ: "Ừ thì... bác cũng chưa mua bảo hiểm bao giờ, sợ đóng tiền vào mà không ốm thì phí ra đấy."
- Sale tạo cảm giác ép mua kèm: Bác từ chối dứt khoát: "Thôi bác không mua bảo hiểm bảo hè gì đâu."

0:50 – 1:40 — Giải thích cơ chế
- Sale giải thích đúng "khoản phòng bị": Bác hỏi thêm chi phí, kiên nhẫn hỏi vài lần.
- Sale dùng thuật ngữ khó: Bác hoang mang hơn.

1:40 – 2:00
- Sale không ép, để bác tự quyết: Bác cầm tài liệu về: "Ừ, cháu cứ đưa bác xem, nhưng bác chưa quyết được đâu, để bác về hỏi ý chồng con bác đã." → WIN
- Sale thúc ép chốt ngay: Bác từ chối dứt khoát. → LOSE'),
('1.4', 1, 'noi-tro-tiet-kiem', 'huong-dan-mbank', 1, 'Cháu bảo gửi qua cái ứng dụng gì đấy lãi cao hơn hả? Nhưng bác xem bác chả hiểu gì.', '["Trấn an và cam kết hướng dẫn từng bước, không chỉ nói \"dễ lắm cứ làm theo\".","Hướng dẫn chậm, dùng ví dụ quen thuộc, để bác tự bấm thay vì giành thao tác hộ.","Chỉ hướng dẫn bằng lời khi bác tự thao tác, tăng dần sự tự tin cho bác."]'::jsonb, '[{"trigger":"Bác sợ bấm nhầm cái gì lại mất tiền ấy.","guidance":"Cam kết ngồi cạnh hướng dẫn từng bước, nêu rõ có bước xác nhận lại trước khi hoàn tất."}]'::jsonb, 'Bác tự thao tác được ít nhất 1 bước trên app và thấy dễ hơn tưởng tượng.', false, 'Bối cảnh: Bác đồng ý mở sổ online để hưởng lãi cao hơn nhưng chưa biết thao tác. Kênh: Quầy.

0:00 – 0:20
Bác: "Cháu bảo gửi qua cái ứng dụng gì đấy lãi cao hơn hả? Nhưng bác xem bác chả hiểu gì."
- Sale trấn an, cam kết hướng dẫn từng bước: Bác yên tâm hơn: "Ừ thì... bác sợ bấm nhầm cái gì lại mất tiền ấy."
- Sale nói "dễ lắm cứ làm theo" không cam kết ngồi cạnh: Bác ngần ngại.

0:20 – 1:10 — Hướng dẫn
- Sale hướng dẫn chậm, ví dụ quen thuộc: Bác làm theo: "Ừ... à được rồi đấy à? Thế xong chưa cháu?"
- Sale nói nhanh, dùng thuật ngữ kỹ thuật: Bác bối rối, thao tác chậm hơn.

1:10 – 1:50 — Tự thao tác
- Sale để bác tự bấm, chỉ hướng dẫn bằng lời: Bác tự tin dần.
- Sale sốt ruột, giành thao tác hộ: Bác thấy mình "dốt": "Thôi cháu làm hộ bác cho nhanh."

1:50 – 2:00
- Bác tự thao tác được ít nhất 1 bước: "Ừ, cũng dễ hơn bác tưởng đấy, cảm ơn cháu nhé." → WIN
- Sale làm hộ hoàn toàn: Bác đồng ý dùng nhưng không tự tin. → LOSE (partial)'),
('2.1', 2, 'nv-van-phong-tre', 'visa-online', 2, 'Alo, bên MSB hả? Mình hỏi thẻ nào hoàn tiền mua sắm online ngon không, mình đang xài Techcombank thấy hoàn ít quá.', '["Giới thiệu tên + vị trí ngắn gọn trước khi trả lời, không mào đầu dài dòng.","Nêu đúng % hoàn tiền + phí cụ thể ngay, so sánh trực tiếp với thẻ My đang dùng.","Trả lời nhanh, có số cụ thể khi My hỏi hạn mức theo lương.","Chốt ngay khi My thấy lợi ích rõ, hướng dẫn đăng ký gọn."]'::jsonb, '[{"trigger":"Ý là được gì cụ thể vậy bạn?","guidance":"Trả lời bằng số liệu cụ thể (% hoàn tiền, phí), tránh nói chung chung \"ưu đãi tốt\"."},{"trigger":"Lương mình tầm 20 triệu, vậy hạn mức được bao nhiêu vậy bạn?","guidance":"Trả lời ngay, tránh \"để em kiểm tra lại rồi gọi lại\" nhiều lần."}]'::jsonb, 'My thấy lợi ích rõ và chủ động hỏi cách đăng ký ngay trong cuộc gọi.', false, 'Bối cảnh: My gọi tổng đài MSB hỏi ưu đãi hoàn tiền sau khi thấy quảng cáo, đang giờ nghỉ trưa. Kênh: Call.

0:00 – 0:15 — Mở đầu
My chủ động gọi: "Alo, bên MSB hả? Mình hỏi thẻ nào hoàn tiền mua sắm online ngon không, mình đang xài Techcombank thấy hoàn ít quá."
- Sale giới thiệu tên + vị trí rõ ràng trước khi trả lời: My tập trung: "Ok, vậy phí năm bao nhiêu vậy bạn?"
- Sale trả lời ngay không xưng danh: My không hỏi lại gay gắt (do My chủ động gọi tới nên ít quan tâm việc này), nhưng vẫn buông 1 câu xác nhận cụt: "Ừ mà bạn tên gì vậy ta?" rồi tiếp tục — không kéo dài.
- Sale mào đầu dài dòng: My ngắt: "Bạn nói gọn giúp mình cái thẻ đó được gì đi, mình sắp họp rồi."

0:15 – 0:50 — So sánh thẻ cũ
- Sale nêu đúng % hoàn tiền + phí cụ thể: My so sánh: "Ừ nghe ổn đó. Thẻ mình đang xài TCB hoàn có 0.5% à, phí lại 500k, đợi mình tí, mình đang nghe máy khác gọi vào."
